/* ---------------- 常量与状态 ---------------- */
const H_SCALE = 0.01;            // 1 场景单位 = 100 米
let V_SCALE = 2.0;               // 垂直比例 2.0 单位/米（≈200× 夸张）
const MAX_DEPTH_M = 30;

const CROSSING_COLOR = 0xffd166;   // 越江标记主色（暖金）
function collectCrossings(lines, riverCfg){
  // 每条线找相邻站对是否匹配 crossings（from→to 或 to→from）
  const out = [];
  if (!riverCfg || !riverCfg.crossings) return out;
  riverCfg.crossings.forEach(cx => {
    lines.forEach(line => {
      const sts = line.stations;
      for (let i = 0; i < sts.length - 1; i++){
        const a = sts[i].name, b = sts[i+1].name;
        if ((a === cx.from && b === cx.to) || (a === cx.to && b === cx.from)){
          out.push({ line, idx: i, label: cx.label || `${line.name}越江`, depth: cx.depth || null });
          break;  // 每个 crossing 只匹配一条线的相邻段（可能多线共线，取先匹配者）
        }
      }
    });
  });
  return out;
}

const state = {
  cityId: METRO_DATA.cities[0].id,
  listCollapsed: true,          // 站点面板默认收起
  focusLineId: '__all__',        // '__all__' 或线路 id
  depthColor: false,
  labels: true,
  strata: true,
  selectedIdx: -1,
  focusIdx: -1,                  // 当前 focus 线路在线路数组中的下标
  trains: true,                 // 列车模拟
  timeline: null,               // 线网生长时间轴（null=当前全网）
  __camTouched: false,          // 用户是否手动转过相机（决定是否写深链 cam 参数）
  night: false,                 // 昼夜模式（夜景）
  screensaver: false,           // 屏保轮播模式
  layers: { landmarks: true, terrain: true, tombs: true, lakes: true, railways: true, annotations: true },
  eraFilter: null,              // 朝代筛选（null=全部；'东汉'/'北魏'…）
                                 // 图层显隐开关
  schedule: true,               // 列车运行时刻制（按当地时间首末班/高峰）
  flyTo: null,
  cruise: null,
  intro: null,
};

/* 深度 → 颜色 */
const DEPTH_STOPS = [[0,'#2FD8A9'],[8,'#37C4F2'],[16,'#6F8CFF'],[22,'#A86BFF'],[30,'#FF6A4D']];
const ELEVATED_COLOR = '#FFC44D';
function depthColor(elevM){
  if (elevM > 0.4) return new THREE.Color(ELEVATED_COLOR);
  const d = Math.max(0, Math.min(MAX_DEPTH_M, -elevM));
  for (let i = 1; i < DEPTH_STOPS.length; i++){
    if (d <= DEPTH_STOPS[i][0]){
      const [d0,c0] = DEPTH_STOPS[i-1], [d1,c1] = DEPTH_STOPS[i];
      return new THREE.Color(c0).lerp(new THREE.Color(c1), (d-d0)/(d1-d0));
    }
  }
  return new THREE.Color(DEPTH_STOPS.at(-1)[1]);
}
function stElev(st){ return st.type === 'elevated' ? st.height : (st.type === 'ground' ? 0 : -st.depth); }

/* ---------------- 场景基础 ---------------- */
const canvas = document.getElementById('c');
let renderer;
try {
  renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
} catch (e) {
  document.getElementById('load-error').style.display = 'block';
  document.getElementById('load-msg').textContent = '当前环境不支持 WebGL，无法渲染三维视图。';
  throw e;
}
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);
renderer.setClearColor(0x060c16);

const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x081020, 0.00055);

const camera = new THREE.PerspectiveCamera(50, innerWidth/innerHeight, 0.5, 6000);
const controls = new window.OrbitControls(camera, canvas);
controls.enableDamping = true;
controls.dampingFactor = 0.08;
controls.maxPolarAngle = Math.PI * 0.52;
controls.autoRotate = !__reduceMotion;
controls.autoRotateSpeed = -0.35;

scene.add(new THREE.AmbientLight(0x88aacc, 1.0));
const dirLight = new THREE.DirectionalLight(0xffffff, 1.4);
dirLight.position.set(120, 260, 160);
scene.add(dirLight);

/* ---------------- 运行时对象 ---------------- */
let world = null;   // { allLines:[...线对象...], focusIdx, group(整个线网容器), bbox, center, size }

function project(lng, lat, origin){
  const x = (lng - origin.lng) * 111320 * Math.cos(origin.lat * Math.PI/180);
  const z = -(lat - origin.lat) * 110540;
  return new THREE.Vector3(x * H_SCALE, 0, z * H_SCALE);
}

/* ---------- 文字标注 ---------- */
function shadeColor(css, f){
  const m = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(String(css).trim());
  if (!m) return css;
  let hx = m[1];
  if (hx.length === 3) hx = hx.split('').map(c => c + c).join('');
  const n = parseInt(hx, 16);
  return `rgb(${Math.round(((n >> 16) & 255) * f)},${Math.round(((n >> 8) & 255) * f)},${Math.round((n & 255) * f)})`;
}

function paintLabelSurface(ctx, W, H, main, sub, subColor, light){
  ctx.clearRect(0, 0, W, H);
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.font = '600 30px "PingFang SC","Microsoft YaHei",sans-serif';
  ctx.lineWidth = 5; ctx.strokeStyle = light ? 'rgba(255,255,255,.95)' : 'rgba(3,8,16,.85)';
  ctx.strokeText(main, W / 2, 30);
  ctx.fillStyle = light ? '#16283c' : '#f0f7ff';
  ctx.fillText(main, W / 2, 30);
  if (sub){
    ctx.font = '500 22px "PingFang SC","Microsoft YaHei",sans-serif';
    ctx.lineWidth = 4; ctx.strokeStyle = light ? 'rgba(255,255,255,.95)' : 'rgba(3,8,16,.85)';
    ctx.strokeText(sub, W / 2, 66);
    ctx.fillStyle = light ? shadeColor(subColor, 0.55) : subColor;
    ctx.fillText(sub, W / 2, 66);
  }
}

function makeLabel(main, sub, subColor){
  const dpr = 2, W = 300, H = 96;
  const cv = document.createElement('canvas');
  cv.width = W*dpr; cv.height = H*dpr;
  const ctx = cv.getContext('2d');
  ctx.scale(dpr, dpr);
  paintLabelSurface(ctx, W, H, main, sub, subColor, __sceneTheme === 'light');
  const tex = new THREE.CanvasTexture(cv);
  tex.colorSpace = THREE.SRGBColorSpace;
  const sp = new THREE.Sprite(new THREE.SpriteMaterial({
    map: tex, transparent: true, depthTest: false, depthWrite: false }));
  sp.renderOrder = 900;   // 标签始终渲染在最上层，避免被建筑/管线遮挡
  sp.scale.set(16.5, 5.3, 1);
  sp.userData.labelText = { main, sub, subColor };
  return sp;
}

/* ---------- 河流单字标注（大字号，逐字沿河排布） ---------- */
function makeRiverChar(ch, pxSize){
  // pxSize：目标屏幕字号（按河流尺度定，大江大字号、小河小字号）
  const dpr = 2, S = 128;
  const cv = document.createElement('canvas');
  cv.width = S * dpr; cv.height = S * dpr;
  const ctx = cv.getContext('2d');
  ctx.scale(dpr, dpr);
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.font = '600 96px "PingFang SC","Microsoft YaHei",sans-serif';
  const light = __sceneTheme === 'light';
  ctx.lineWidth = 9; ctx.strokeStyle = light ? 'rgba(255,255,255,.95)' : 'rgba(3,12,24,.88)';
  ctx.strokeText(ch, S / 2, S / 2 + 4);
  ctx.fillStyle = light ? '#1a4a7a' : '#d3ecff';
  ctx.fillText(ch, S / 2, S / 2 + 4);
  const tex = new THREE.CanvasTexture(cv);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  const sp = new THREE.Sprite(new THREE.SpriteMaterial({
    map: tex, transparent: true, depthTest: false, depthWrite: false }));
  sp.renderOrder = 900;
  sp.userData.alwaysVisible = true;
  sp.userData.riverChar = true;
  sp.userData.riverPx = pxSize;
  sp.userData.riverCh = ch;
  riverChars.push(sp);
  sp.scale.set(pxSize * 0.8, pxSize * 0.8, 1);
  return sp;
}

/* ---------- 黄浦江 ---------- */
function buildRiver(origin, city){
  const cfg = city && city.river;
  if (!cfg || !cfg.points || cfg.points.length < 2) return null;

  const kx = 111320 * Math.cos(origin.lat*Math.PI/180) * H_SCALE;
  const kz = 110540 * H_SCALE;
  const grp = new THREE.Group();
  const name = cfg.name || '河流';

  // 逐条水系（主线 + 可选支流）
  const segs = [{ pts: cfg.points, w: cfg.widthM || 500, wStart: cfg.startWidthM, wEnd: cfg.endWidthM, n: name }]
    .concat((cfg.branches || []).map(b => ({ pts: b.points, w: b.widthM || 300, wStart: b.startWidthM, wEnd: b.endWidthM, n: b.name || '' })));

  segs.forEach(seg => {
    if (!seg.pts || seg.pts.length < 2) return;
    const ctr = seg.pts.map(([lng,lat]) =>
      new THREE.Vector3((lng-origin.lng)*kx, 0.06, -(lat-origin.lat)*kz));
    // 平滑：加密采样，让轨迹更自然
    const curve = new THREE.CatmullRomCurve3(ctr, false, 'centripetal');
    const N = Math.max(40, ctr.length * 6);
    const pts = [];
    for (let i = 0; i <= N; i++) pts.push(curve.getPointAt(i / N));
    const wStart = ((seg.wStart || seg.w) / 2) * H_SCALE;
    const wEnd   = ((seg.wEnd   || seg.w) / 2) * H_SCALE;
    const wAt = t => wStart + (wEnd - wStart) * t;

    // 1) 江面（带状三角面）
    const verts = [], idx = [];
    pts.forEach((p, i) => {
      const a = pts[Math.max(0, i-1)], b = pts[Math.min(pts.length-1, i+1)];
      const dir = new THREE.Vector3().subVectors(b, a).normalize();
      const n = new THREE.Vector3(-dir.z, 0, dir.x);
      const w = wAt(pts.length > 1 ? i / (pts.length - 1) : 0);
      verts.push(p.clone().addScaledVector(n, -w), p.clone().addScaledVector(n, w));
    });
    for (let i = 0; i < pts.length - 1; i++){
      const l = i*2, r = i*2+1;
      idx.push(l, l+2, r, r, l+2, r+2);
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(verts.flatMap(v=>[v.x,v.y,v.z]), 3));
    g.setIndex(idx);
    const water = new THREE.Mesh(g, new THREE.MeshBasicMaterial({
      color: cfg.color || 0x2a7fb8, transparent: true, opacity: 0.82,
      depthWrite: false, side: THREE.DoubleSide }));
    water.renderOrder = 1;
    grp.add(water);

    // 流向流光（沿河道滑动的半透明亮条，示意水流方向；海湾/港/海峡不设流向）
    const isBay = /(湾|港)$/.test(cfg.name || '') || cfg.name === '鹭江';
    if (pts.length > 2 && !isBay && !__reduceMotion){
      const flowN = Math.min(24, Math.max(3, Math.round(pts.length / 3)));
      const flowMat = new THREE.MeshBasicMaterial({ color: cfg.centerColor || 0x8fd8ff,
        transparent: true, opacity: 0.32, depthWrite: false, side: THREE.DoubleSide });
      for (let k = 0; k < flowN; k++){
        const flow = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), flowMat.clone());
        flow.rotation.x = -Math.PI / 2;
        flow.renderOrder = 2;
        flow.userData = { t: k / flowN, speed: 0.055 + (k % 3) * 0.012, curvePts: pts,
                          widthAt: wAt };
        flow.userData.mat = flowMat;
        grp.add(flow);
        riverFlows.push(flow);
      }
    }

    // 2) 岸线描边（两侧轮廓）
    [-1, 1].forEach(side => {
      const edge = [];
      pts.forEach((p, i) => {
        const a = pts[Math.max(0, i-1)], b = pts[Math.min(pts.length-1, i+1)];
        const dir = new THREE.Vector3().subVectors(b, a).normalize();
        const n = new THREE.Vector3(-dir.z, 0, dir.x);
        const wt = wAt(pts.length > 1 ? i / (pts.length - 1) : 0);
        edge.push(p.clone().addScaledVector(n, side * wt).setY(0.12));
      });
      const eg = new THREE.BufferGeometry().setFromPoints(
        edge.flatMap((p, i) => (i < edge.length - 1 ? [p, edge[i+1]] : [])));
      grp.add(new THREE.LineSegments(eg, new THREE.LineBasicMaterial({
        color: cfg.edgeColor || 0x63b8e6, transparent: true, opacity: 0.72 })));
    });

    // 3) 中线发光参考轨迹
    const cg = new THREE.BufferGeometry().setFromPoints(
      pts.flatMap((p, i) => (i < pts.length - 1 ? [p.clone().setY(0.18), pts[i+1].clone().setY(0.18)] : [])
    ));
    grp.add(new THREE.LineSegments(cg, new THREE.LineBasicMaterial({
      color: cfg.centerColor || 0xa8e4ff, transparent: true, opacity: 0.75 })));

    // 4) 河名标注：逐字沿河道排布，字号按河流尺度（大江大字 / 小河小字），每条河仅标一次
    if (seg.n){
      const chars = [...seg.n];
      const wM = seg.w || 300;
      // 屏幕字号：14~34px，与河宽正相关
      const px = Math.max(14, Math.min(34, 10 + wM / 55));
      // 字距（世界单位）：以参考距离 800 时的字宽为基准，留 25% 间距
      const sRef = 800 * px * 0.00097;
      const gapWorld = Math.max(8, sRef * 1.25);
      const curveLen = Math.max(1, curve.getLength());
      const gapU = Math.min(0.18, gapWorld / curveLen);
      const cu = 0.5;   // 单处标注，置于河道中段
      chars.forEach((ch, i) => {
        const u = cu + (i - (chars.length - 1) / 2) * gapU;
        const uu = Math.min(0.985, Math.max(0.015, u));
        const p = curve.getPointAt(uu);
        const lb = makeRiverChar(ch, px);
        lb.position.set(p.x, 1.6, p.z);
        grp.add(lb);
      });
    }
  });

  groupLabelLayer(grp);
  return grp;
}

/* 河流标注需在标签 LOD 之外常显，单独标记 */
function groupLabelLayer(grp){
  grp.traverse(o => { if (o.isSprite) o.userData.alwaysVisible = true; });
}

/* ---------- 城市天际线（InstancedMesh） ---------- */
function mulberry32(a){ return function(){
  a |= 0; a = a + 0x6D2B79F5 | 0;
  let t = Math.imul(a ^ a>>>15, 1|a);
  t = t + Math.imul(t ^ t>>>7, 61|t) ^ t;
  return ((t ^ t>>>14)>>>0) / 4294967296; }; }
function buildBuildings(origin, lines){
  const rng = mulberry32(20261112);
  const items = [];
  lines.forEach(l => l.stations.forEach(s => {
    if (rng() > 0.5) return;
    const n = 1 + Math.floor(rng() * 2);
    for (let i = 0; i < n; i++){
      // 与站点保持距离，避免高楼压住站名标签
      const ang = rng() * Math.PI * 2;
      const dist = 0.006 + rng() * 0.006;     // ≈600~1300m 外
      const plng = s.lng + Math.cos(ang) * dist;
      const plat = s.lat + Math.sin(ang) * dist * 0.8;
      const tall = rng() * rng();
      items.push([plng, plat, 8 + tall * 70, 26 + rng() * 46]);
    }
  }));
  if (!items.length) return new THREE.Group();
  const geo = new THREE.BoxGeometry(1,1,1); geo.translate(0,.5,0);
  const mat = new THREE.MeshStandardMaterial({ color: 0x243f5e, roughness: .9, metalness: .05,
    emissive: 0x0d1e36, emissiveIntensity: 0.8 });
  mat.userData.themeRole = 'buildings';
  const mesh = new THREE.InstancedMesh(geo, mat, items.length);
  const M = new THREE.Matrix4();
  items.forEach(([lng,lat,hM,fM],i) => {
    const p = project(lng,lat,origin);
    M.makeScale(fM*H_SCALE, hM*H_SCALE*3.2, fM*H_SCALE);
    M.setPosition(p.x, 0, p.z);
    mesh.setMatrixAt(i, M);
  });
  mesh.instanceMatrix.needsUpdate = true;
  return mesh;
}

/* ---------- 构建整网 ---------- */
const grouped = new THREE.Group();       // 常驻：环境（地面/江/建筑/地层参考面）
let lineGroups = [];                     // 每条线路一个 Group
let allMarkers = [], allLabels = [];
let globalLabelInfo = [];                // 与 allLabels 一一对应 {lineIdx, stIdx}
const riverChars = [];                   // 河流逐字标注（随距离缩放）
const riverFlows = [];                  // 河道流光（沿流向移动的亮条）
let lineStMeta = {};                     // lineId -> { mesh, meta[], transferMesh }

function lineObjKey(l){ return l.branchOf ? l.branchOf + '|' + l.id : l.id; }

/* ================================================================
 * 中国超级桥梁：三维效果渲染
 *   - 桥面（发光带）、桥塔、斜拉索 / 悬索主缆+吊索、山谷地形
 *   - 支持跨海 / 跨江 / 跨山谷三种类型
 * ================================================================ */
/* ================================================================
 * 地标建筑：用组合几何体塑造可辨识的城市地标
 *   类型：tv_tower / twist / taper / opener / pagoda / pavilion /
 *          castle / tower / gate / corn / ancient / wheel
 * ================================================================ */
function makeLandmarkMesh(type, hH, wW, colorStr){
  const grp = new THREE.Group();
  const main = new THREE.Color(colorStr || '#9fd3f0');
  const glass = new THREE.MeshStandardMaterial({
    color: main, emissive: main.clone().multiplyScalar(0.35), emissiveIntensity: 1.0,
    roughness: 0.28, metalness: 0.55 });
  const accent = new THREE.MeshStandardMaterial({
    color: 0xffd166, emissive: 0x8a6420, emissiveIntensity: 1.2, roughness: .3, metalness: .4 });
  const stone = new THREE.MeshStandardMaterial({
    color: 0xc8b898, emissive: 0x3a3020, emissiveIntensity: .8, roughness: .9 });
  const W = Math.max(1.2, wW);

  if (type === 'tv_tower'){
    // 三根斜柱 + 三球串塔 + 天线
    for (let i = 0; i < 3; i++){
      const a = i * Math.PI * 2 / 3;
      const leg = new THREE.Mesh(new THREE.CylinderGeometry(W * 0.16, W * 0.30, hH * 0.55, 6), glass);
      leg.position.set(Math.cos(a) * W * 0.5, hH * 0.275, Math.sin(a) * W * 0.5);
      leg.rotation.z = Math.cos(a) * 0.16;
      leg.rotation.x = -Math.sin(a) * 0.16;
      grp.add(leg);
    }
    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(W * 0.10, W * 0.14, hH * 0.92, 8), glass);
    shaft.position.y = hH * 0.46; grp.add(shaft);
    const balls = [[0.52, 0.30], [0.72, 0.20], [0.88, 0.13]];  // [y 比例, 半径比例]
    balls.forEach(([ry, rr]) => {
      const b = new THREE.Mesh(new THREE.SphereGeometry(W * rr * 1.5, 14, 10),
        new THREE.MeshStandardMaterial({ color: 0xe86a9a, emissive: 0x7a2048, emissiveIntensity: 1.1,
          roughness: .35, metalness: .5 }));
      b.position.y = hH * ry; grp.add(b);
    });
    const ant = new THREE.Mesh(new THREE.CylinderGeometry(W * 0.04, W * 0.07, hH * 0.16, 6), accent);
    ant.position.y = hH * 0.96; grp.add(ant);
  } else if (type === 'twist'){
    // 扭转上升：多段方形逐层旋转 + 收分
    const N = 12;
    for (let i = 0; i < N; i++){
      const t = i / N;
      const side = W * (1 - t * 0.45);
      const seg = new THREE.Mesh(new THREE.BoxGeometry(side, hH / N * 1.02, side), glass);
      seg.position.y = hH * (t + 0.5 / N);
      seg.rotation.y = t * 0.9;
      grp.add(seg);
    }
    const tip = new THREE.Mesh(new THREE.ConeGeometry(W * 0.28, hH * 0.10, 8), glass);
    tip.position.y = hH * 1.03; grp.add(tip);
  } else if (type === 'taper'){
    // 收分塔楼（下宽上窄）+ 顶部锥
    const N = 7;
    for (let i = 0; i < N; i++){
      const t = i / N;
      const side = W * (1 - t * 0.62);
      const seg = new THREE.Mesh(new THREE.BoxGeometry(side, hH / N * 1.02, side), glass);
      seg.position.y = hH * (t + 0.5 / N);
      grp.add(seg);
    }
    const tip = new THREE.Mesh(new THREE.ConeGeometry(W * 0.19, hH * 0.09, 4), glass);
    tip.position.y = hH * 1.02; grp.add(tip);
  } else if (type === 'opener'){
    // 开瓶器：主楼 + 顶部两侧立柱 + 横梁（中间留洞）
    const body = new THREE.Mesh(new THREE.BoxGeometry(W, hH * 0.84, W * 0.7), glass);
    body.position.y = hH * 0.42; grp.add(body);
    [-1, 1].forEach(s => {
      const leg = new THREE.Mesh(new THREE.BoxGeometry(W * 0.22, hH * 0.2, W * 0.6), glass);
      leg.position.set(s * W * 0.39, hH * 0.92, 0); grp.add(leg);
    });
    const bridge = new THREE.Mesh(new THREE.BoxGeometry(W, hH * 0.09, W * 0.6), glass);
    bridge.position.y = hH * 0.99; grp.add(bridge);
  } else if (type === 'pagoda'){
    // 阶梯塔楼（金茂式）
    const N = 6;
    for (let i = 0; i < N; i++){
      const t = i / N;
      const side = W * (1 - t * 0.55);
      const seg = new THREE.Mesh(new THREE.BoxGeometry(side, hH / N * 1.04, side), glass);
      seg.position.y = hH * (t + 0.5 / N) ;
      grp.add(seg);
    }
    const crown = new THREE.Mesh(new THREE.ConeGeometry(W * 0.2, hH * 0.12, 6), accent);
    crown.position.y = hH * 1.03; grp.add(crown);
  } else if (type === 'pavilion'){
    // 斗拱倒锥（世博中国馆 / 环球中心）
    const base = new THREE.Mesh(new THREE.CylinderGeometry(W * 0.55, W * 0.75, hH * 0.25, 6), glass);
    base.position.y = hH * 0.125; grp.add(base);
    const body = new THREE.Mesh(new THREE.ConeGeometry(W * 1.05, hH * 0.7, 4, 1, true), glass);
    body.rotation.y = Math.PI / 4;
    body.position.y = hH * 0.60; grp.add(body);
    const cap = new THREE.Mesh(new THREE.BoxGeometry(W * 0.7, hH * 0.08, W * 0.7), glass);
    cap.position.y = hH * 0.98; grp.add(cap);
  } else if (type === 'castle'){
    // 城堡：中心塔 + 四角塔楼 + 尖顶
    const keep = new THREE.Mesh(new THREE.CylinderGeometry(W * 0.5, W * 0.55, hH * 0.7, 10), stone);
    keep.position.y = hH * 0.35; grp.add(keep);
    const roof = new THREE.Mesh(new THREE.ConeGeometry(W * 0.58, hH * 0.35, 10), accent);
    roof.position.y = hH * 0.875; grp.add(roof);
    [[-1, -1], [-1, 1], [1, -1], [1, 1]].forEach(([sx, sz]) => {
      const tw = new THREE.Mesh(new THREE.CylinderGeometry(W * 0.18, W * 0.2, hH * 0.5, 8), stone);
      tw.position.set(sx * W * 0.62, hH * 0.25, sz * W * 0.62); grp.add(tw);
      const tr = new THREE.Mesh(new THREE.ConeGeometry(W * 0.24, hH * 0.22, 8), accent);
      tr.position.set(sx * W * 0.62, hH * 0.61, sz * W * 0.62); grp.add(tr);
    });
  } else if (type === 'gate'){
    // 门形双塔：两根斜柱 + 顶部连接
    [-1, 1].forEach(s => {
      const leg = new THREE.Mesh(new THREE.BoxGeometry(W * 0.28, hH * 0.92, W * 0.5), glass);
      leg.position.set(s * W * 0.55, hH * 0.46, 0);
      leg.rotation.z = -s * 0.10;
      grp.add(leg);
    });
    const top = new THREE.Mesh(new THREE.BoxGeometry(W * 1.25, hH * 0.10, W * 0.5), glass);
    top.position.y = hH * 0.96; grp.add(top);
  } else if (type === 'corn'){
    // 椭圆塔（大玉米式）
    const body = new THREE.Mesh(new THREE.CylinderGeometry(W * 0.42, W * 0.55, hH * 0.9, 12), glass);
    body.position.y = hH * 0.45; grp.add(body);
    const top = new THREE.Mesh(new THREE.SphereGeometry(W * 0.44, 12, 8, 0, Math.PI * 2, 0, Math.PI / 2), accent);
    top.position.y = hH * 0.9; grp.add(top);
  } else if (type === 'ancient'){
    // 仿古：台基 + 多层塔身 + 攒尖顶
    const base = new THREE.Mesh(new THREE.BoxGeometry(W * 1.6, hH * 0.16, W * 1.6), stone);
    base.position.y = hH * 0.08; grp.add(base);
    const body = new THREE.Mesh(new THREE.BoxGeometry(W * 1.1, hH * 0.5, W * 1.1), stone);
    body.position.y = hH * 0.41; grp.add(body);
    const roof1 = new THREE.Mesh(new THREE.ConeGeometry(W * 0.95, hH * 0.22, 4), accent);
    roof1.rotation.y = Math.PI / 4; roof1.position.y = hH * 0.77; grp.add(roof1);
    const roof2 = new THREE.Mesh(new THREE.ConeGeometry(W * 0.68, hH * 0.18, 4), accent);
    roof2.rotation.y = Math.PI / 4; roof2.position.y = hH * 0.92; grp.add(roof2);
    const fin = new THREE.Mesh(new THREE.SphereGeometry(W * 0.10, 8, 6), accent);
    fin.position.y = hH * 1.01; grp.add(fin);
  } else if (type === 'wheel'){
    // 环形雕塑（五月的风）
    const torus = new THREE.Mesh(new THREE.TorusGeometry(W * 0.75, W * 0.16, 10, 28),
      new THREE.MeshStandardMaterial({ color: main, emissive: main.clone().multiplyScalar(.4),
        emissiveIntensity: 1.1, roughness: .35, metalness: .45 }));
    torus.position.y = hH * 0.55; grp.add(torus);
    const base = new THREE.Mesh(new THREE.CylinderGeometry(W * 0.5, W * 0.7, hH * 0.12, 10), stone);
    base.position.y = hH * 0.06; grp.add(base);
  } else if (type === 'grotto'){
    // 石窟：崖壁造像（佛龛群 + 主窟）
    const cliff = new THREE.Mesh(new THREE.BoxGeometry(W * 2.8, hH * 0.9, W * 0.55), stone);
    cliff.position.y = hH * 0.45; grp.add(cliff);
    const nicheMat = new THREE.MeshStandardMaterial({ color: 0x2a1f14, roughness: .95 });
    for (let k = 0; k < 5; k++){
      const niche = new THREE.Mesh(
        new THREE.CylinderGeometry(W * 0.16, W * 0.16, W * 0.2, 10, 1, false, 0, Math.PI), nicheMat);
      niche.rotation.x = Math.PI / 2;
      niche.position.set((k - 2) * W * 0.52, hH * (0.30 + 0.18 * (k % 2)), W * 0.31);
      grp.add(niche);
    }
    const cave = new THREE.Mesh(
      new THREE.CylinderGeometry(W * 0.26, W * 0.26, W * 0.26, 10, 1, false, 0, Math.PI), nicheMat);
    cave.rotation.x = Math.PI / 2;
    cave.position.set(0, hH * 0.55, W * 0.32);
    grp.add(cave);
  } else {
    // 通用高层：柱体 + 顶部装饰
    const body = new THREE.Mesh(new THREE.BoxGeometry(W, hH, W * 0.75), glass);
    body.position.y = hH * 0.5; grp.add(body);
    const cap = new THREE.Mesh(new THREE.CylinderGeometry(W * 0.06, W * 0.4, hH * 0.06, 6), accent);
    cap.position.y = hH * 1.02; grp.add(cap);
  }
  return grp;
}

function buildCityLandmarks(city, origin, container){
  if (!city.landmarks || !city.landmarks.length) return null;
  const grp = new THREE.Group();
  // 地标真实高度 × 夸张倍率（线网尺度下才可见；与示意建筑群 3.2× 区分，用 8×）
  const K = 8.0;
  city.landmarks.forEach(lm => {
    const p = project(lm.lng, lm.lat, origin);
    const hH = Math.max(3, lm.h * H_SCALE * K);          // 世界高度
    const wW = Math.max(2.0, hH * 0.13);                 // 世界宽度（按高度推断）
    const mesh = makeLandmarkMesh(lm.type, hH, wW, lm.color);
    mesh.position.set(p.x, 0, p.z);
    mesh.userData.landmark = lm;
    grp.add(mesh);
    // 地面光环（标示位置）
    const ring = new THREE.Mesh(new THREE.RingGeometry(wW * 0.9, wW * 1.25, 24),
      new THREE.MeshBasicMaterial({ color: new THREE.Color(lm.color || '#9fd3f0'),
        transparent: true, opacity: .5, side: THREE.DoubleSide, depthWrite: false }));
    ring.rotation.x = -Math.PI / 2;
    ring.position.set(p.x, 0.35, p.z);
    grp.add(ring);
    // 名称 + 高度标注
    const lb = makeLabel(lm.name, lm.desc || `${lm.h}m`, lm.color || '#9fd3f0');
    lb.position.set(p.x, hH + 4.5 + (city.landmarks.indexOf(lm) % 4) * 9.5, p.z);
    lb.scale.set(17, 5.4, 1);
    lb.userData.alwaysVisible = true;
    grp.add(lb);
    allLabels.push(lb);
    globalLabelInfo.push({ landmark: true });
  });
  if (container) container.add(grp);
  return grp;
}

function buildBridgeWorld(city, doFit = true){
  const bridges = city.bridges;
  // 投影原点 = 所有桥控制点质心
  let sLng = 0, sLat = 0, n = 0;
  bridges.forEach(b => b.points.forEach(([lng, lat]) => { sLng += lng; sLat += lat; n++; }));
  const origin = { lng: sLng / n, lat: sLat / n };

  const root = new THREE.Group();
  const bridgeGroups = [];
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;

  bridges.forEach((b, bi) => {
    const grp = buildOneBridge(b, origin, bi);
    root.add(grp.group);
    bridgeGroups.push(grp);
    minX = Math.min(minX, grp.bbox.min.x); maxX = Math.max(maxX, grp.bbox.max.x);
    minZ = Math.min(minZ, grp.bbox.min.z); maxZ = Math.max(maxZ, grp.bbox.max.z);
  });

  const cx = (minX + maxX) / 2, cz = (minZ + maxZ) / 2;
  const size = Math.max(maxX - minX, maxZ - minZ);

  // 地面网格（全国尺度参考）
  const grid = new THREE.GridHelper(size + 200, 80, 0x1d3a5c, 0x112640);
  grid.material.transparent = true; grid.material.opacity = .35;
  grid.position.set(cx, -0.5, cz);
  grouped.add(grid);

  world = { city, lines: [], origin, root, grouped, center: new THREE.Vector3(cx, 0, cz),
    size, bridgeGroups, strataGroup: null, crossingGroup: null };
  lineGroups = [];
  state.focusIdx = -1;

  scene.add(root);
  world.root = root;
  buildUIList();
  updateStats();
  updateLegend();
  if (doFit){
    // 全国尺度下总览过远：默认聚焦第一座桥，用户可从下拉切回「全部大桥」
    if (world.city.bridges.length) focusBridge(0);
    else fitAll();
  }
}

function buildOneBridge(b, origin, bi){
  const grp = new THREE.Group();
  const pts = b.points.map(([lng, lat]) => project(lng, lat, origin));
  const curve = new THREE.CatmullRomCurve3(pts, false, 'centripetal');
  const N = 140;
  const samples = [];
  for (let i = 0; i <= N; i++) samples.push(curve.getPointAt(i / N));

  const deckY = b.deckH;
  const halfW = b.width / 2;
  const col = new THREE.Color(b.color);
  const isValley = !!b.valley;
  const hasWater = b.cat === '跨海' || b.cat === '跨江';

  // ---- 水面（跨海/跨江桥下方的大面积半透明水面） ----
  if (hasWater){
    const bbox0 = new THREE.Box3().setFromPoints(samples);
    const wSize = Math.max(bbox0.max.x - bbox0.min.x, bbox0.max.z - bbox0.min.z) * 1.6 + 60;
    const wD = Math.min(wSize * 0.55, 200);
    const water = new THREE.Mesh(
      new THREE.PlaneGeometry(wSize, wD),
      new THREE.MeshBasicMaterial({ color: 0x14507a, transparent: true, opacity: 0.42, depthWrite: false }));
    water.rotation.x = -Math.PI / 2;
    const mid0 = curve.getPointAt(0.5);
    water.position.set(mid0.x, -1.5, mid0.z);
    water.renderOrder = 0;
    grp.add(water);
    // 水面波纹线（横向淡色线条，营造水面感）
    const rippleMat = new THREE.LineBasicMaterial({ color: 0x6db8e0, transparent: true, opacity: 0.18 });
    const mid = curve.getPointAt(0.5);
    for (let k = -2; k <= 2; k++){
      if (k === 0) continue;
      const y = mid0.z + k * wD / 6;
      const seg = [new THREE.Vector3(mid0.x - wSize/2, -1.4, y), new THREE.Vector3(mid0.x + wSize/2, -1.4, y)];
      grp.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(seg), rippleMat));
    }
  }

  // ---- 桥墩（非山谷桥，在无塔区段下方设置圆柱桥墩） ----
  const pierMat = new THREE.MeshStandardMaterial({
    color: 0xa8b8c8, emissive: 0x2a3a4a, emissiveIntensity: .7, roughness: .75 });
  if (!isValley && hasWater){
    const pierStep = Math.max(6, (b.lenKm || 5) * 0.01 * 100);  // 每 0.01×全长放一个
    const count = Math.min(14, Math.max(3, Math.floor(N / 14)));
    for (let k = 1; k < count; k++){
      const u = k / count;
      // 跳过桥塔附近（塔本身是支撑）
      if ((b.towers || []).some(t => Math.abs(t - u) < 0.04)) continue;
      const pt = curve.getPointAt(u);
      const pierH = deckY + 1.5;
      const pier = new THREE.Mesh(new THREE.CylinderGeometry(halfW * 0.30, halfW * 0.42, pierH, 8), pierMat);
      pier.position.set(pt.x, pierH / 2 - 1.2, pt.z);
      grp.add(pier);
      // 墩顶承台（短横梁）
      const cap = new THREE.Mesh(new THREE.BoxGeometry(halfW * 1.3, 0.8, halfW * 0.9), pierMat);
      cap.position.set(pt.x, deckY - 0.5, pt.z);
      grp.add(cap);
    }
  }

  // ---- 桥面（发光带 + 箱梁侧面 + 栏杆线） ----
  {
    const deckThickness = 1.1;
    const verts = [], idx = [];
    // 顶面 + 底面 + 两侧面（箱梁）
    samples.forEach((p, i) => {
      const a = samples[Math.max(0, i - 1)], c = samples[Math.min(N, i + 1)];
      const dir = new THREE.Vector3().subVectors(c, a).normalize();
      const nrm = new THREE.Vector3(-dir.z, 0, dir.x);
      const l = p.clone().setY(deckY).addScaledVector(nrm, -halfW);
      const r = p.clone().setY(deckY).addScaledVector(nrm, halfW);
      verts.push(l, r);                                        // 顶面
      verts.push(l.clone().setY(deckY - deckThickness), r.clone().setY(deckY - deckThickness));  // 底面
    });
    for (let i = 0; i < samples.length - 1; i++){
      const t = i * 4, b = i * 4 + 2;
      // 顶面
      idx.push(t, t + 2, t + 1, t + 1, t + 2, t + 3);
      // 底面
      idx.push(b, b + 1, b + 2, b + 1, b + 3, b + 2);
      // 左侧面
      idx.push(t, b, t + 2, t + 2, b, b + 2);
      // 右侧面
      idx.push(t + 1, t + 3, b + 1, b + 1, t + 3, b + 3);
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(verts.flatMap(v => [v.x, v.y, v.z]), 3));
    g.setIndex(idx);
    grp.add(new THREE.Mesh(g, new THREE.MeshStandardMaterial({
      color: col, emissive: col.clone().multiplyScalar(.55), emissiveIntensity: 1.0,
      roughness: .5, metalness: .2, side: THREE.DoubleSide })));
    // 桥面边缘发光
    [-1, 1].forEach(side => {
      const edge = [];
      samples.forEach((p, i) => {
        const a = samples[Math.max(0, i - 1)], c = samples[Math.min(N, i + 1)];
        const dir = new THREE.Vector3().subVectors(c, a).normalize();
        const nrm = new THREE.Vector3(-dir.z, 0, dir.x);
        edge.push(p.clone().setY(deckY + .25).addScaledVector(nrm, side * halfW));
      });
      const seg = edge.flatMap((p, i) => i < edge.length - 1 ? [p, edge[i + 1]] : []);
      grp.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(seg),
        new THREE.LineBasicMaterial({ color: 0xffffff, transparent: true, opacity: .55 })));
    });
  }

  const towerMat = new THREE.MeshStandardMaterial({
    color: 0xd8e4f0, emissive: 0x35506e, emissiveIntensity: .8, roughness: .6 });
  const cableMat = new THREE.LineBasicMaterial({
    color: col.clone().lerp(new THREE.Color(0xffffff), .45), transparent: true, opacity: .85 });

  // ---- 桥塔（斜拉桥 H 形双柱 + 横梁；悬索桥门形塔） + 斜拉索 ----
  const towerTops = [];
  (b.towers || []).forEach(tRatio => {
    const p = curve.getPointAt(tRatio);
    const th = b.towerH;
    // H 形双柱
    [-1, 1].forEach(s => {
      const leg = new THREE.Mesh(new THREE.BoxGeometry(halfW * 0.9, th, halfW * 0.8), towerMat);
      leg.position.set(p.x, deckY + th / 2, p.z + s * halfW * 0.75);
      grp.add(leg);
    });
    // 上横梁
    const beam = new THREE.Mesh(new THREE.BoxGeometry(halfW * 0.6, halfW * 0.5, halfW * 0.8), towerMat);
    beam.position.set(p.x, deckY + th * 0.92, p.z);
    grp.add(beam);
    // 下横梁
    const beam2 = new THREE.Mesh(new THREE.BoxGeometry(halfW * 0.6, halfW * 0.35, halfW * 0.8), towerMat);
    beam2.position.set(p.x, deckY + th * 0.30, p.z);
    grp.add(beam2);
    towerTops.push({ p, topY: deckY + th, ratio: tRatio });

    if (b.type === 'cable' || b.type === 'truss') {
      [-1, 1].forEach(side => {
        for (let k = 1; k <= 9; k++) {
          const u = tRatio + side * k * 0.010;
          if (u <= 0 || u >= 1) continue;
          const anchor = curve.getPointAt(u);
          const seg = [
            new THREE.Vector3(p.x, deckY + th, p.z + side * halfW * 0.75),
            new THREE.Vector3(anchor.x, deckY + .4, anchor.z)];
          const g = new THREE.BufferGeometry().setFromPoints(seg);
          grp.add(new THREE.LineSegments(g, cableMat));
        }
      });
    }
  });

  // ---- 航空障碍灯（塔顶红色球体） ----
  towerTops.forEach(tt => {
    const light = new THREE.Mesh(new THREE.SphereGeometry(halfW * 0.14, 6, 6),
      new THREE.MeshBasicMaterial({ color: 0xff2222 }));
    light.position.set(tt.p.x, tt.topY + halfW * 0.14, tt.p.z);
    light.userData.navLight = true;
    grp.add(light);
  });

  // ---- 悬索：主缆 + 吊索 ----
  if (b.type === 'suspension' && towerTops.length >= 2){
    const [t1, t2] = towerTops;
    const sag = b.towerH * 0.42;
    const M = 40;
    const mainPts = [];
    for (let i = 0; i <= M; i++){
      const t = i / M;
      const x = t1.p.x + (t2.p.x - t1.p.x) * t;
      const z = t1.p.z + (t2.p.z - t1.p.z) * t;
      const y = t1.topY - sag * Math.sin(Math.PI * t);
      mainPts.push(new THREE.Vector3(x, y, z));
    }
    [-1, 1].forEach(side => {
      const off = halfW * 0.95;
      const ptsOff = mainPts.map(p => new THREE.Vector3(p.x, p.y, p.z + side * off));
      const seg = ptsOff.flatMap((p, i) => i < ptsOff.length - 1 ? [p, ptsOff[i + 1]] : []);
      grp.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(seg),
        new THREE.LineBasicMaterial({ color: 0xffffff, transparent: true, opacity: .7 })));
      for (let i = 1; i < M; i += 2){
        const cp = mainPts[i];
        const seg2 = [
          new THREE.Vector3(cp.x, cp.y, cp.z + side * off),
          new THREE.Vector3(cp.x, deckY + .4, cp.z + side * off),
        ];
        grp.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(seg2),
          new THREE.LineBasicMaterial({ color: col.clone().lerp(new THREE.Color(0xffffff), .3),
            transparent: true, opacity: .45 })));
      }
    });
  }

  // ---- 跨山谷：多峰山脊 + 谷底蜿蜒河流 ----
  if (isValley){
    const vd = b.valleyDepth || 50;
    const valleyMat = new THREE.MeshStandardMaterial({
      color: 0x1e4030, emissive: 0x0a2015, emissiveIntensity: 1, roughness: .95 });
    const ridgeMat = new THREE.MeshStandardMaterial({
      color: 0x2a5040, emissive: 0x0e2418, emissiveIntensity: 1, roughness: .92 });
    const spanX = Math.max(Math.abs(samples[0].x - samples[N].x), Math.abs(samples[0].z - samples[N].z)) || 1;
    const dirH = new THREE.Vector3().subVectors(samples[N], samples[0]).normalize();
    const dirP = new THREE.Vector3(-dirH.z, 0, dirH.x);
    // 每侧 6 个错落山峰
    [-1, 1].forEach(side => {
      for (let k = 0; k < 6; k++){
        const u = 0.5 + side * (0.10 + k * 0.075);
        const uu = Math.min(1, Math.max(0, u));
        const bp = curve.getPointAt(uu);
        const peakH = vd * (0.68 + 0.32 * Math.sin(k * 2.1 + side));
        const rr = spanX * (0.18 + 0.05 * Math.sin(k * 1.7));
        const hill = new THREE.Mesh(new THREE.ConeGeometry(rr, peakH, 5), k % 2 ? valleyMat : ridgeMat);
        hill.position.set(bp.x + dirP.x * side * rr * 0.5, peakH / 2 - 2, bp.z + dirP.z * side * rr * 0.5);
        grp.add(hill);
      }
    });
    // 谷底蜿蜒河流（带状 mesh）
    const rivVerts = [], rivIdx = [];
    const rN = 24, rivW = Math.max(1.5, spanX * 0.03);
    for (let i = 0; i <= rN; i++){
      const t = i / rN;
      const u = 0.08 + t * 0.84;
      const bp = curve.getPointAt(Math.min(1, Math.max(0, u)));
      const wOff = Math.sin(t * Math.PI * 4) * spanX * 0.04;
      rivVerts.push(bp.x + wOff - rivW, 0.15, bp.z - rivW * 0.5);
      rivVerts.push(bp.x + wOff + rivW, 0.15, bp.z + rivW * 0.5);
    }
    for (let i = 0; i < rN; i++){
      const l = i * 2, r = i * 2 + 1;
      rivIdx.push(l, l + 2, r, r, l + 2, r + 2);
    }
    const rg = new THREE.BufferGeometry();
    rg.setAttribute('position', new THREE.Float32BufferAttribute(rivVerts, 3));
    rg.setIndex(rivIdx);
    const river = new THREE.Mesh(rg, new THREE.MeshBasicMaterial({
      color: 0x4a90b8, transparent: true, opacity: 0.65, depthWrite: false, side: THREE.DoubleSide }));
    river.renderOrder = 0;
    grp.add(river);
  }

  // ---- 桥名 + 关键数据标注 ----
  {
    const mid = curve.getPointAt(0.5);
    const labelTop = deckY + (b.towerH || 20) + 10;
    const lb = makeLabel(b.name, `${b.cat} · ${b.lenKm} km · ${b.type === 'suspension' ? '悬索桥' : b.type === 'cable' ? '斜拉桥' : b.type === 'truss' ? '钢桁梁桥' : ''}`, b.color);
    lb.position.set(mid.x, labelTop, mid.z);
    const ls = THREE.MathUtils.clamp(b.lenKm * 0.55 + 8, 10, 30);
    lb.scale.set(ls, ls * 0.32, 1);
    lb.userData.alwaysVisible = true;
    grp.add(lb);
    allLabels.push(lb);
    globalLabelInfo.push({ bridge: true });
  }

  const bbox = new THREE.Box3().setFromPoints(samples.map(p => p.clone().setY(deckY)));
  return { bridge: b, bi, group: grp, bbox, center: bbox.getCenter(new THREE.Vector3()),
           size: Math.max(bbox.max.x - bbox.min.x, bbox.max.z - bbox.min.z) };
}

function focusBridge(idx){
  if (!world || !world.bridgeGroups) return;
  const bg = world.bridgeGroups[idx];
  if (!bg) return;
  state.focusIdx = -1;
  const target = bg.center.clone();
  target.y = bg.bridge.deckH * 0.8;
  const dist = Math.max(bg.size * 1.15, 60);
  const dir = new THREE.Vector3(0.25, 0.55, 0.8).normalize();
  const camPos = target.clone().addScaledVector(dir, dist);
  state.flyTo = { from: camera.position.clone(), to: camPos,
    fromT: controls.target.clone(), toT: target, t: 0 };
  // 高亮选中桥
  world.bridgeGroups.forEach((g, i) => {
    g.group.traverse(o => {
      if (o.material && o.material.opacity !== undefined){
        if (o.material.userData._base === undefined) o.material.userData._base = o.material.opacity;
        o.material.opacity = i === idx ? o.material.userData._base : o.material.userData._base * 0.35;
      }
    });
  });
  // 更新下拉
  const sel = document.getElementById('sel-line');
  if (sel) sel.value = 'bridge-' + idx;
  // 信息卡
  const info = document.getElementById('info-card');
  document.getElementById('ic-idx').textContent = String(idx + 1).padStart(2, '0');
  document.getElementById('ic-name').textContent = bg.bridge.name;
  document.getElementById('ic-chips').innerHTML =
    `<span class="chip t" style="border-color:${bg.bridge.color};color:${bg.bridge.color}">${bg.bridge.cat}</span>` +
    `<span class="chip">${bg.bridge.type === 'suspension' ? '悬索桥' : bg.bridge.type === 'cable' ? '斜拉桥' : '钢桁梁桥'}</span>` +
    `<span class="chip">${bg.bridge.year} 年</span>`;
  document.getElementById('ic-depth').innerHTML =
    `全长 <b>${bg.bridge.lenKm}</b> km · 主跨 <b>${bg.bridge.mainSpanM}</b> m` +
    (bg.bridge.towerHm ? ` · 塔高 <b>${bg.bridge.towerHm}</b> m` : '');
  document.getElementById('ic-note').textContent = bg.bridge.desc || '';
  info.classList.add('show');
}

function buildWorld(doFit = true){
  if (world){ scene.remove(world.root); disposeObj(world.root); }
  __airportPlanes = [];
  trainsMesh = null; trains.length = 0;
  if (world){ world.tombMeshes = null; world.tombItems = null; }
  if (world) world.railwayGroups = null;
  // 常驻环境容器跨城市复用：必须清空，否则上一城市的水系/地面残留到下一城市
  while (grouped.children.length) grouped.remove(grouped.children[0]);
  allMarkers = []; allLabels = []; globalLabelInfo = []; lineStMeta = {}; riverChars.length = 0; riverFlows.length = 0;
  state._labelOwners = new Set();

  const city = METRO_DATA.cities.find(c => c.id === state.cityId);
  // 桥梁主题：独立渲染分支
  if (city.kind === 'bridges') return buildBridgeWorld(city, doFit);
  const lines = city.lines;

  // 全市投影原点 = 所有站坐标的质心
  let sLng = 0, sLat = 0, n = 0;
  lines.forEach(l => l.stations.forEach(s => { sLng += s.lng; sLat += s.lat; n++; }));
  const origin = { lng: sLng/n, lat: sLat/n };

  const root = new THREE.Group();
  const poiGroups = {
    landmarks: new THREE.Group(), terrain: new THREE.Group(), tombs: new THREE.Group(),
    lakes: new THREE.Group(), railways: new THREE.Group(), annotations: new THREE.Group(),
  };
  Object.values(poiGroups).forEach(g => root.add(g));
  // —— 环境层 ——
  {
    let minLng=Infinity, minLat=Infinity, maxLng=-Infinity, maxLat=-Infinity;
    lines.forEach(l => l.stations.forEach(s => {
      minLng=Math.min(minLng,s.lng); maxLng=Math.max(maxLng,s.lng);
      minLat=Math.min(minLat,s.lat); maxLat=Math.max(maxLat,s.lat);
    }));
    const pad = (maxLng-minLng)*0.02;
    const pMin = project(minLng-pad, minLat-pad, origin);
    const pMax = project(maxLng+pad, maxLat+pad, origin);
    const cx = (pMin.x+pMax.x)/2, cz = (pMin.z+pMax.z)/2;
    const sx = pMax.x-pMin.x, sz = pMax.z-pMin.z;

    const ground = new THREE.Mesh(new THREE.PlaneGeometry(sx+140, sz+140),
      new THREE.MeshBasicMaterial({ color: 0x0d1c30, transparent: true, opacity: .5, side: THREE.DoubleSide, depthWrite: false }));
    ground.material.userData.themeRole = 'ground';
    ground.rotation.x = -Math.PI/2; ground.position.set(cx,0,cz); ground.renderOrder = 2;
    grouped.add(ground);

    const grid = new THREE.GridHelper(Math.max(sx,sz)+160, 96, 0x1d3a5c, 0x112640);
    grid.material.transparent = true; grid.material.opacity = .5;
    grid.position.set(cx, 0.02, cz);
    grouped.add(grid);

    const river = buildRiver(origin, city);
    if (river) grouped.add(river);
    grouped.add(buildBuildings(origin, lines));
    buildCityLandmarks(city, origin, poiGroups.landmarks);
    const trn = buildCityTerrain(city, origin);
    if (trn){ poiGroups.terrain.add(trn); worldTerrainGroup = trn; }

    world = { city, lines, origin, root, grouped, poiGroups, landmarkGroup: worldLandmarkGroup, terrainGroup: worldTerrainGroup, center: new THREE.Vector3(cx,0,cz),
      size: Math.max(sx,sz),
      lineSize: (() => {
        // 仅按线路站点计算尺度（河流/建筑群不参与取景，否则小城市相机过远）
        let a = Infinity, b = -Infinity, c2 = Infinity, d2 = -Infinity;
        lines.forEach(l => l.stations.forEach(s => {
          const p = project(s.lng, s.lat, origin);
          a = Math.min(a, p.x); b = Math.max(b, p.x);
          c2 = Math.min(c2, p.z); d2 = Math.max(d2, p.z);
        }));
        return Math.max(b - a, d2 - c2, 50);
      })() };
    root.add(grouped);
  }

  // 同名站（换乘站）中心点：用于标签统一定位，避免多线标签位置错开
  const nameCenters = new Map();
  {
    const acc = new Map();
    lines.forEach(l => l.stations.forEach(s => {
      const p = project(s.lng, s.lat, origin);
      const a = acc.get(s.name) || { x: 0, z: 0, n: 0 };
      a.x += p.x; a.z += p.z; a.n++;
      acc.set(s.name, a);
    }));
    acc.forEach((a, k) => nameCenters.set(k, { x: a.x / a.n, z: a.z / a.n }));
  }

  // —— 各线路对象 ——
  lineGroups = lines.map((line, li) => {
    const lg = makeLineGroup(line, li, origin, nameCenters);
    if (lg) root.add(lg.group);
    return lg;
  });

  // 地层参考面（全市，-10/-20/-30m）
  const strataGroup = new THREE.Group();
  [[10,0x1d4a3a],[20,0x1d3a58],[30,0x3a2450]].forEach(([d,c]) => {
    const pm = new THREE.Mesh(new THREE.PlaneGeometry(world.size+220, world.size+220),
      new THREE.MeshBasicMaterial({ color: c, transparent: true, opacity: .07, side: THREE.DoubleSide, depthWrite: false }));
    pm.rotation.x = -Math.PI/2;
    pm.position.set(world.center.x, -d*V_SCALE, world.center.z);
    pm.renderOrder = 3;
    strataGroup.add(pm);
    const lb = makeLabel('', `−${d} m`, '#6d8aa5');
    lb.scale.set(9, 3.6, 1);
    lb.position.set(world.center.x - world.size/2 - 14, -d*V_SCALE, world.center.z + world.size/2 + 8);
    strataGroup.add(lb);
  });
  strataGroup.visible = state.strata;
  grouped.add(strataGroup);

  // 聚焦线路高亮/淡化其余
  applyFocus();

  // —— 越江地铁段高亮标记 ——
  const crossingGroup = new THREE.Group();
  const riverCfg = city.river;
  const crossings = riverCfg ? collectCrossings(lines, riverCfg) : [];
  crossings.forEach((cx, ki) => {
    const lg = lineGroups.find(g => g.line === cx.line);
    if (!lg) return;
    // 越江段中点（在江面上方）
    const curve = lg.group.userData.curve;
    if (!curve) return;
    const p0 = curve.getPointAt(0);
    // 用两个相邻站定位线段的中点（曲线参数空间近似）
    const a = project(cx.line.stations[cx.idx].lng, cx.line.stations[cx.idx].lat, origin);
    const b = project(cx.line.stations[cx.idx+1].lng, cx.line.stations[cx.idx+1].lat, origin);
    const mid = a.clone().add(b).multiplyScalar(0.5);
    mid.y = 0.35;   // 江面上方

    // 发光脉冲环（双层环 + 上下浮动）
    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(3.4, 0.55, 10, 34),
      new THREE.MeshBasicMaterial({ color: CROSSING_COLOR, transparent: true, opacity: 0.95 }));
    ring.rotation.x = Math.PI / 2;
    ring.position.copy(mid);
    ring.userData.crossing = { t: 0, ki };
    crossingGroup.add(ring);

    const ring2 = new THREE.Mesh(
      new THREE.TorusGeometry(4.6, 0.22, 8, 32),
      new THREE.MeshBasicMaterial({ color: 0xfff3c4, transparent: true, opacity: 0.65 }));
    ring2.rotation.x = Math.PI / 2;
    ring2.position.copy(mid);
    ring2.userData.crossing = { t: Math.PI, ki };
    crossingGroup.add(ring2);

    // 江面标签
    const lb = makeLabel(cx.label || '越江隧道',
      cx.depth ? `最大埋深约 ${cx.depth} m` : '', '#ffd166');
    lb.scale.set(15, 4.8, 1);
    lb.position.set(mid.x, mid.y + 5.5, mid.z);
    lb.userData.alwaysVisible = true;
    crossingGroup.add(lb);

    // 从江面到管线的垂直指示线（虚线感：用半透 Line）
    const lg2 = lineGroups.find(g => g.line === cx.line);
    // 找到该段管线的实际中点高度
    const ys = [cx.line.stations[cx.idx]._elev, cx.line.stations[cx.idx+1]._elev];
    const midY = ((ys[0] + ys[1]) / 2) * V_SCALE;
    const geo = new THREE.BufferGeometry().setFromPoints([
      mid.clone().setY(0.3), mid.clone().setY(midY)]);
    crossingGroup.add(new THREE.LineSegments(geo, new THREE.LineBasicMaterial(
      { color: CROSSING_COLOR, transparent: true, opacity: 0.55 })));
  });
  if (crossings.length) root.add(crossingGroup);
  world.crossingGroup = crossingGroup;

  scene.add(root);
  world.root = root;
  world.strataGroup = strataGroup;
  {
    const sf = ensureSnow();
    sf.visible = city.climate === 'snow' && !__reduceMotion;
  }
  buildCityRailways(city, origin, poiGroups.railways);
  buildCityAirports(city, origin, poiGroups.railways);
  buildCityAnnotations(city, origin, poiGroups.annotations);
  buildCityTombs(city, origin, poiGroups.tombs);
  buildCityLakes(city, origin, poiGroups.lakes);
  applySceneTheme(__sceneTheme);
  applyLayers();
  buildTrains(root, lineGroups);
  updateProfile();
  if (doFit) fitAll();
  buildUIList();
  updateStats();
  updateLegend();
  syncUrl();
}

const _dropPos = [];
function makeLineGroup(line, li, origin, nameCenters){
  const sts = line.stations.map((s,j) => {
    s._i = j; s._elev = stElev(s);
    return { st: s, pos: project(s.lng, s.lat, origin) };
  });
  const pts = sts.map(a => new THREE.Vector3(a.pos.x, a.st._elev*V_SCALE, a.pos.z));
  const group = new THREE.Group();

  // 管线
  const tubular = Math.max(140, Math.min(720, sts.length*16));
  const curve = new THREE.CatmullRomCurve3(pts, !!line.loop, 'centripetal');
  const tubeGeo = new THREE.TubeGeometry(curve, tubular, 1.25, 10, false);
  group.userData.curve = curve;

  if (state.depthColor){
    const anchorUs = [];
    const NS = 900, sample = [];
    for (let i=0;i<=NS;i++) sample.push(curve.getPointAt(i/NS));
    sts.forEach(a => {
      let best=0, bd=Infinity;
      sample.forEach((p,j) => { const dd=p.distanceToSquared(pts[a.st._i]); if (dd<bd){bd=dd;best=j;} });
      anchorUs.push(best/NS);
    });
    const colors = new Float32Array(tubeGeo.attributes.position.count*3);
    const ringVerts = 11;
    const c = new THREE.Color();
    for (let v=0; v<tubeGeo.attributes.position.count; v++){
      const u = Math.min(1, Math.floor(v/ringVerts)/tubular);
      let e = sts[0].st._elev;
      for (let i=1; i<anchorUs.length; i++){
        if (u <= anchorUs[i] || i === anchorUs.length-1){
          const span = anchorUs[i]-anchorUs[i-1];
          e = sts[i-1].st._elev + (sts[i].st._elev-sts[i-1].st._elev)*(span>0?(u-anchorUs[i-1])/span:0);
          break;
        }
      }
      c.copy(depthColor(e));
      colors[v*3]=c.r; colors[v*3+1]=c.g; colors[v*3+2]=c.b;
    }
    tubeGeo.setAttribute('color', new THREE.BufferAttribute(colors,3));
    group.add(new THREE.Mesh(tubeGeo, new THREE.MeshStandardMaterial({
      vertexColors: true, roughness:.35, metalness:.15, emissive:0x223344, emissiveIntensity:.6 })));
  } else {
    const col = new THREE.Color(line.color);
    group.add(new THREE.Mesh(tubeGeo, new THREE.MeshStandardMaterial({
      color: col, roughness:.35, metalness:.15, emissive: col.clone().multiplyScalar(.38) })));
  }

  // 地面投影参考线
  const flat = pts.map(p => new THREE.Vector3(p.x, 0.25, p.z));
  group.add(new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(flat,!!line.loop,'centripetal'), Math.max(200, sts.length*8), 0.3, 6, false),
    new THREE.MeshBasicMaterial({ color: new THREE.Color(line.color), transparent: true, opacity: .25 })));

  // 站点：球体(instanced) + 垂线 + 地面环(instanced) + 换乘环(instanced) + 标签
  const sphereGeo = new THREE.SphereGeometry(1.75, 14, 10);
  const ringGeo = new THREE.RingGeometry(1.75, 2.5, 20); ringGeo.rotateX(-Math.PI/2);
  const torusGeo = new THREE.TorusGeometry(3.1, .36, 6, 20); torusGeo.rotateX(Math.PI/2);

  const markerMesh = new THREE.InstancedMesh(sphereGeo,
    new THREE.MeshStandardMaterial({ roughness: .3, metalness: .05 }), sts.length);
  const ringMesh = new THREE.InstancedMesh(ringGeo,
    new THREE.MeshBasicMaterial({ transparent:true, opacity:.7, side:THREE.DoubleSide, depthWrite:false }),
    sts.length);
  const transferIdx = sts.map((a, i) => (a.st.transfer && a.st.transfer.length) ? i : -1).filter(i => i >= 0);
  const transferMesh = transferIdx.length
    ? new THREE.InstancedMesh(torusGeo,
        new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: .85 }), transferIdx.length)
    : null;

  const dropPos = [];
  const M = new THREE.Matrix4();
  const tmpCol = new THREE.Color();
  const stMeta = [];   // 与 markerMesh 实例一一对应，供射线命中后的定位
  // 换乘站标签去重：同一站名只由"首条出现该站的线路"绘制标签
  const seenBefore = state._labelOwners || (state._labelOwners = new Set());
  sts.forEach((a, i) => {
    const st = a.st, y = st._elev*V_SCALE;
    const col = state.depthColor ? depthColor(st._elev) : new THREE.Color(st.type==='elevated' ? ELEVATED_COLOR : line.color);
    M.makeTranslation(a.pos.x, y, a.pos.z);
    markerMesh.setMatrixAt(i, M);
    markerMesh.setColorAt(i, col);
    tmpCol.copy(col);
    stMeta.push({ x: a.pos.x, y, z: a.pos.z, lineIdx: li, stIdx: i });
    dropPos.push(a.pos.x, y, a.pos.z, a.pos.x, 0, a.pos.z);
    M.makeTranslation(a.pos.x, .1, a.pos.z);
    ringMesh.setMatrixAt(i, M);
    const sub = st.type==='elevated' ? `↑ 高架 ${st.height}m`
             : st.type==='ground' ? '地面'
             : `↓ ${st.depth}m${st.transfer ? ' · 换'+st.transfer.join('/') : ''}`;
    // 同城同名的换乘站只画一个标签（避免图上重复出现 2-4 次）
    const labelKey = st.name;
    if (!seenBefore.has(labelKey)){
      seenBefore.add(labelKey);
      const lb = makeLabel(st.name, sub, st.type==='elevated' ? '#FFC44D' : '#9fd8ff');
      const ctr = (nameCenters && nameCenters.get(st.name)) || { x: a.pos.x, z: a.pos.z };
      lb.position.set(ctr.x, 3.6 + (i%2)*2.4, ctr.z);
      group.add(lb); allLabels.push(lb);
      globalLabelInfo.push({ lineIdx: li, stIdx: i });
    }
  });
  if (markerMesh.instanceColor){
    markerMesh.instanceColor.needsUpdate = true;
    markerMesh.material.emissive = new THREE.Color(0x1a2a3a);
    markerMesh.material.emissiveIntensity = 0.9;
  }
  transferIdx.forEach((si, k) => {
    const a = sts[si];
    M.makeTranslation(a.pos.x, a.st._elev*V_SCALE, a.pos.z);
    transferMesh.setMatrixAt(k, M);
  });
  markerMesh.instanceMatrix.needsUpdate = true;
  ringMesh.instanceMatrix.needsUpdate = true;
  if (transferMesh) transferMesh.instanceMatrix.needsUpdate = true;

  group.add(markerMesh);
  group.add(ringMesh);
  if (transferMesh) group.add(transferMesh);
  lineStMeta[line.id] = { mesh: markerMesh, meta: stMeta, transferMesh, transferIdx };
  group.add(ringMesh);
  const dropGeo = new THREE.BufferGeometry();
  dropGeo.setAttribute('position', new THREE.Float32BufferAttribute(dropPos, 3));
  group.add(new THREE.LineSegments(dropGeo, new THREE.LineBasicMaterial({ color: 0x7fb8d8, transparent:true, opacity:.4 })));

  const bbox = new THREE.Box3().setFromPoints(pts);
  return { line, li, group, bbox, markers: [],
           center: bbox.getCenter(new THREE.Vector3()), size: Math.max(bbox.max.x-bbox.min.x, bbox.max.z-bbox.min.z) };
}

function applyFocus(){
  if (!world) return;
  const focus = state.focusLineId;
  lineGroups.forEach(lg => {
    const isFocus = focus === '__all__' || lineObjKey(lg.line) === focus ||
                    (lg.line.branchOf && lg.line.branchOf === focus);
    lg.dim = !isFocus;
    lg.group.traverse(o => {
      const mats = o.material ? (Array.isArray(o.material) ? o.material : [o.material]) : [];
      mats.forEach(mm => {
        if (mm && typeof mm.opacity === 'number'){
          if (mm.userData._baseOp === undefined) mm.userData._baseOp = mm.opacity;
          const base = mm.userData._baseOp;
          mm.transparent = true;
          mm.opacity = base * (lg.dim ? 0.14 : 1);
          void o;
        }
      });
    });
  });
  state.focusIdx = focus === '__all__' ? -1 : world.lines.findIndex(l => lineObjKey(l) === focus);
}

function disposeObj(root){
  root.traverse(o => {
    if (o.geometry) o.geometry.dispose();
    if (o.material){
      (Array.isArray(o.material) ? o.material : [o.material]).forEach(m => { if (m.map) m.map.dispose(); if (!m.userData._shared) m.dispose(); });
    }
  });
}

/* ---------------- 相机适配 ---------------- */
function fitAll(instant){
  const w = world;
  let target = w.center.clone(), size = w.lineSize || w.size;
  if (state.focusIdx >= 0){
    const lg = lineGroups[state.focusIdx];
    if (lg){ target = lg.center.clone(); size = lg.size; }
  }
  target.y = -V_SCALE * 9;
  const dist = size * 0.85;
  const dir = new THREE.Vector3(0.15, 0.58, 0.92).normalize();
  const camPos = target.clone().addScaledVector(dir, dist);
  controls.target.copy(target);
  if (instant){
    camera.position.copy(camPos);
    camera.near = Math.max(0.5, dist/4000); camera.far = Math.max(dist*60, size*40);
    camera.updateProjectionMatrix();
    controls.minDistance = size*0.04; controls.maxDistance = size*3;
    controls.update();
  } else {
    state.flyTo = { from: camera.position.clone(), to: camPos, fromT: controls.target.clone(), toT: target, t: 0 };
  }
}

/* ---------------- UI ---------------- */
const $ = id => document.getElementById(id);

const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

function populateSelectors(){
  const city = METRO_DATA.cities.find(c => c.id === state.cityId);
  const selCity = $('sel-city'), selLine = $('sel-line');
  // 按线路数分组：主干线网（≥10线）在前，其余按线路数降序
  const cities = [...METRO_DATA.cities].sort((a, b) => {
    if (a.kind === 'bridges') return 1;
    if (b.kind === 'bridges') return -1;
    const la = (a.lines || []).length, lb = (b.lines || []).length;
    if (la !== lb) return lb - la;
    return a.name.localeCompare(b.name, 'zh');
  });
  const big = cities.filter(c => c.kind !== 'bridges' && (c.lines || []).length >= 10);
  const small = cities.filter(c => c.kind !== 'bridges' && (c.lines || []).length < 10);
  const bri = cities.filter(c => c.kind === 'bridges');
  const fmt = c => {
    const cnt = c.lines ? `${c.lines.length}线/${c.lines.reduce((a,l)=>a+l.stations.length,0)}站` : `${(c.bridges||[]).length}桥`;
    return `<option value="${esc(c.id)}">${esc(c.name)}（${cnt}）</option>`;
  };
  let recentHtml = '';
  try {
    const rc = JSON.parse(localStorage.getItem('metro3d-recent') || '[]')
      .filter(id => id !== state.cityId && cities.some(c => c.id === id)).slice(0, 3);
    if (rc.length){
      recentHtml = `<optgroup label="🕘 最近访问">` +
        rc.map(id => fmt(cities.find(c => c.id === id))).join('') + `</optgroup>`;
    }
  } catch(err){ __recErr('citySelect', err && err.message, 'populateSelectors'); }
  selCity.innerHTML =
    recentHtml +
    `<optgroup label="主要线网（≥10 线）">${big.map(fmt).join('')}</optgroup>` +
    (small.length ? `<optgroup label="其他城市">${small.map(fmt).join('')}</optgroup>` : '') +
    (bri.length ? `<optgroup label="专题">${bri.map(fmt).join('')}</optgroup>` : '');
  const opts = [];
  if (city.kind === 'bridges'){
    opts.push('<option value="__all__">全部大桥 · 全国总览</option>');
    city.bridges.forEach((b, i) => opts.push(`<option value="bridge-${i}">${b.name} · ${b.cat} ${b.lenKm}km</option>`));
  } else {
    opts.push('<option value="__all__">全部线路 · 网络总览</option>');
    city.lines.forEach(l => {
      opts.push(`<option value="${lineObjKey(l)}">${l.name} · ${l.loop ? '环线' : l.from + '—' + l.to}</option>`);
    });
  }
  selLine.innerHTML = opts.join('') + '<option disabled>更多线路 · 敬请期待</option>';
  selCity.value = state.cityId;
  selLine.value = state.focusLineId;
}

function updateStats(){
  const w = world;
  if (w.city.kind === 'bridges'){
    const bs = w.city.bridges;
    const crossSea = bs.filter(b => b.cat === '跨海').length;
    const crossRiver = bs.filter(b => b.cat === '跨江').length;
    const crossValley = bs.filter(b => b.cat === '跨山谷').length;
    $('stat-line').innerHTML = `<b>中国超级桥梁</b> · ${bs.length} 座 · 跨海 ${crossSea} · 跨江 ${crossRiver} · 跨山谷 ${crossValley}<br>` +
      `点击桥梁查看三维效果与工程数据`;
    $('btn-list-toggle').textContent = `桥梁 ${bs.length}`;
    const fc = $('float-count'); if (fc) fc.textContent = bs.length;
    return;
  }
  const totalSt = w.lines.reduce((a,l) => a + l.stations.length, 0);
  const focus = state.focusIdx >= 0 ? w.lines[state.focusIdx] : null;
  /* v1.9.0：埋深范围按当前城市实际最大埋深动态显示（如京张高铁 0~102m）。
     色带仍按 MAX_DEPTH_M 归一，精确刻度看剖面对比面板。 */
  const maxDepth = w.lines.reduce((a, l) => Math.max(a,
    ...l.stations.map(s => (s.type === 'underground' ? (s.depth || 0) : 0))), 0);
  $('stat-line').innerHTML = focus
    ? `<b>${focus.name}</b> · ${focus.loop ? '环线' : focus.from + ' ↔ ' + focus.to} · 约 ${focus.lengthKm} km<br>` +
      `${focus.stations.length} 站 · 线路色 <span style="color:${focus.color}">■</span>（深度为示意值）`
    : `<b>${w.city.name}轨道交通线网</b> · ${w.lines.length} 条线路 · ${totalSt} 座车站<br>` +
      `全线地下埋深示意 0~${maxDepth || MAX_DEPTH_M} m · 点击线路可聚焦查看`;
  $('btn-list-toggle').textContent = `站点 ${totalSt}`;
  const fc = $('float-count'); if (fc) fc.textContent = focus ? focus.stations.length : totalSt;
}

function updateLegend(){
  const w = world;
  if (w.city.kind === 'bridges'){
    $('legend').innerHTML = `
      <div class="lg-row"><span class="lg-chip" style="background:#00A6A6"></span>斜拉桥 / 悬索桥 / 桁梁桥（按线路色区分）</div>
      <div class="lg-row"><span class="lg-chip" style="background:#FFC44D"></span>桥塔与主缆</div>
      <div class="lg-row" style="font-size:10px">点击列表或下拉选择单座桥梁查看特写</div>`;
    return;
  }
  const grad = `linear-gradient(90deg, ${DEPTH_STOPS.map(([d,c])=>`${c} ${d/MAX_DEPTH_M*100}%`).join(',')})`;
  let html = '';
  if (state.depthColor){
    html = `<div class="lg-row"><span class="lg-grad" style="background:${grad}"></span><span>埋深着色（全网络）</span></div>
      <div class="lg-num"><span>0m</span><span>浅</span><span>${MAX_DEPTH_M}m 深</span></div>
      <div class="lg-row"><span class="lg-chip" style="background:${ELEVATED_COLOR}"></span>高架段</div>`;
  } else {
    const focus = state.focusIdx >= 0 ? w.lines[state.focusIdx] : null;
    const shown = focus ? [focus] : w.lines.filter(l => !l.branchOf);
    html = `<div class="lg-grid">${shown.map(l =>
      `<button class="lg-chip-btn" data-id="${lineObjKey(l)}" title="${l.name}"><i style="background:${l.color}"></i><span>${l.name.replace('（市域）','')}${l.branchOf?'支':''}</span></button>`).join('')}</div>`;
    html += `<div class="lg-row"><span class="lg-chip" style="background:${ELEVATED_COLOR}"></span>高架段</div>
      <div class="lg-row"><span class="lg-ring"></span>换乘站</div>`;
  }
  if (world.city.landmarks && world.city.landmarks.length && !state.depthColor){
    html += `<div class="lg-row" style="font-size:10px;margin-top:4px">◆ 地标建筑 ${world.city.landmarks.length} 座（名称+高度标注）</div>`;
  }
  $('legend').innerHTML = html;
  $('legend').querySelectorAll('.lg-chip-btn').forEach(b => {
    b.addEventListener('click', () => {
      state.focusLineId = b.dataset.id;
      $('sel-line').value = state.focusLineId;
      rebuild();
    });
  });
}

function buildUIList(){
  const box = $('st-list');
  box.innerHTML = '';
  const w = world;
  // 桥梁主题：桥列表
  if (w.city.kind === 'bridges'){
    w.city.bridges.forEach((b, i) => {
      const row = document.createElement('button');
      row.className = 'st-row';
      row.innerHTML = `<span class="st-idx">${String(i+1).padStart(2,'0')}</span>
        <span class="st-name">${b.name}</span>
        <span class="st-tr">${b.cat}</span>
        <span class="st-depth" style="color:${b.color}">${b.lenKm}km</span>`;
      row.addEventListener('click', () => focusBridge(i));
      box.appendChild(row);
    });
    return;
  }
  const focus = state.focusIdx >= 0 ? [w.lines[state.focusIdx]] : w.lines;
  focus.forEach(line => {
    const gHead = document.createElement('button');
    gHead.className = 'grp-head';
    gHead.innerHTML = `<i style="background:${line.color}"></i><span>${line.name} · ${line.stations.length}站</span><b>${line.from}—${line.to}</b>`;
    if (state.focusIdx >= 0){
      gHead.classList.add('open');
      const b = document.createElement('div');
      b.className = 'grp-body'; b.dataset.g = lineObjKey(line);
      line.stations.forEach((st,j) => {
        const row = document.createElement('button');
        row.className = 'st-row'; row.dataset.idx = j; row.dataset.line = lineObjKey(line);
        const dTxt = st.type==='elevated' ? `↑${st.height}m` : st.type==='ground' ? '地面' : `−${st.depth}m`;
        const dCol = '#' + (state.depthColor ? depthColor(st._elev) : new THREE.Color(line.color)).getHexString();
        const nTr = (st.transfer || []).length;
        row.innerHTML = `<span class="st-idx">${String(j+1).padStart(2,'0')}</span>
          <span class="st-name">${st.name}${nTr ? `<b style="color:#7fd4ff;font-weight:400">（${nTr + 1}线）</b>` : ''}</span>
          <span class="st-depth" style="color:${dCol}">${dTxt}</span>`;
        row.addEventListener('click', () => focusStation(line, j));
        b.appendChild(row);
      });
      box.appendChild(gHead);
      box.appendChild(b);
      return;
    }
    gHead.addEventListener('click', () => {
      const body = box.querySelector(`.grp-body[data-g="${lineObjKey(line)}"]`);
      if (body){ body.style.display = body.style.display === 'none' ? '' : 'none';
        gHead.classList.toggle('open', body.style.display !== 'none'); }
      else {
        const b = document.createElement('div');
        b.className = 'grp-body'; b.dataset.g = lineObjKey(line);
        line.stations.forEach((st,j) => {
          const row = document.createElement('button');
          row.className = 'st-row'; row.dataset.idx = j; row.dataset.line = lineObjKey(line);
          const dTxt = st.type==='elevated' ? `↑${st.height}m` : st.type==='ground' ? '地面' : `−${st.depth}m`;
          const dCol = '#' + (state.depthColor ? depthColor(st._elev) : new THREE.Color(line.color)).getHexString();
          row.innerHTML = `<span class="st-idx">${String(j+1).padStart(2,'0')}</span>
            <span class="st-name">${st.name}</span>
            ${st.transfer && !state.depthColor ? `<span class="st-tr">换 ${st.transfer.join('/')}</span>` : ''}
            <span class="st-depth" style="color:${dCol}">${dTxt}</span>`;
          row.addEventListener('click', () => focusStation(state.focusIdx >= 0 ? line : chooseLineByStation(line,j), j));
          b.appendChild(row);
        });
        gHead.parentNode.insertBefore(b, gHead.nextSibling);
        gHead.classList.add('open');
      }
    });
    box.appendChild(gHead);
  });
}

/* 全部模式下点击某站 → 该站所在线路对象 */
function chooseLineByStation(line, idx){ return line; }

function focusStation(lineObj, idx){
  const st = lineObj.stations[idx];
  state.focusLineId = lineObjKey(lineObj);
  $('sel-line').value = state.focusLineId;
  state.selectedIdx = idx;
  state.selectedLine = lineObj.id;
  rebuild(true);
  const lg = lineGroups.find(g => g.line === lineObj);
  const pos = project(st.lng, st.lat, world.origin);
  const size = lg ? lg.size : world.size;
  const target = new THREE.Vector3(pos.x, st._elev*V_SCALE*0.5, pos.z);
  const camPos = target.clone().add(new THREE.Vector3(size*0.06, size*0.055, size*0.075));
  state.flyTo = { from: camera.position.clone(), to: camPos, fromT: controls.target.clone(), toT: target, t: 0 };
  showInfoCard(lineObj, idx);
}

function showInfoCard(line, i){
  const st = line.stations[i];
  $('ic-idx').textContent = String(i+1).padStart(2,'0');
  $('ic-name').textContent = st.name + '站';
  const chips = [`<span class="chip ${st.type==='elevated'?'e':st.type==='ground'?'u':'u'}">${st.type==='elevated'?'高架车站':st.type==='ground'?'地面车站':'地下车站'}</span>`,
                 `<span class="chip t" style="border-color:${line.color};color:${line.color}">${line.name}</span>`];
  if (st.transfer) chips.push(`<span class="chip t">换乘 ${st.transfer.map(t=>/^[0-9]+$/.test(t)?t+'号线':t).join(' · ')}</span>`);
  $('ic-chips').innerHTML = chips.join('');
  if (st.type==='elevated'){
    $('ic-depth').innerHTML = `轨面高 <b>+${st.height}</b> m（高架段）`;
  } else {
    const pct = Math.round(st.depth / MAX_DEPTH_M * 100);
    // 换乘站：列出同城同名站在各线的深度（真实多层站台）
    let extra = '';
    if (st.transfer && st.transfer.length && world && world.lines){
      const siblings = [];
      world.lines.forEach(o => {
        if (o.id === line.id) return;
        o.stations.forEach(os => {
          if (os.name !== st.name) return;
          const d = os.type === 'underground' ? `−${os.depth}m` :
                    os.type === 'elevated' ? `+${os.height}m（高架）` : '地面';
          siblings.push(`<span style="color:${o.color}">${o.name} ${d}</span>`);
        });
      });
      if (siblings.length){
        extra = `<div style="margin-top:7px;font-size:10.5px;color:var(--text-dim);line-height:1.7">
          各线站台：${siblings.join(' · ')}</div>`;
      }
    }
    $('ic-depth').innerHTML = `站台埋深 <b>−${st.depth}</b> m
      <div class="ic-bar"><i style="width:${pct}%;background:#${depthColor(st._elev).getHexString()}"></i></div>${extra}`;
  }
  const noteEl = $('ic-note');
  if (st.depthSource){
    const isUrl = /^https?:\/\//.test(st.depthSource);
    noteEl.innerHTML = (st.note ? esc(st.note) + '<br>' : '') +
      (isUrl ? `✓ 埋深有实测引用：<a href="${esc(st.depthSource)}" target="_blank" rel="noopener" style="color:var(--accent)">资料链接</a>`
             : `✓ 埋深依据：${esc(st.depthSource)}`);
  } else {
    noteEl.textContent = st.note || (st.transfer ? '换乘站' : '');
  }
  $('info-card').classList.add('show');
}

/* ---------------- 交互 ---------------- */
const ray = new THREE.Raycaster();
const ptr = new THREE.Vector2();
let downXY = null;
canvas.addEventListener('pointerdown', e => {
  if (state.screensaver) exitScreensaver();
  downXY = [e.clientX, e.clientY];
  controls.autoRotate = false;
  stopCruise();
  resetIdle();
});
controls.addEventListener('start', () => { state.__camTouched = true; syncUrl(); });
canvas.addEventListener('pointerup', e => {
  if (!downXY) return;
  const moved = Math.hypot(e.clientX-downXY[0], e.clientY-downXY[1]);
  downXY = null;
  if (moved > 7){ state.__camTouched = true; syncUrl(); return; }   // 拖拽改变视角 → 深链记录相机
  if (nationMode){                    // 🌌 星图模式：点击城市 → 俯冲进入
    ptr.x = (e.clientX/innerWidth)*2-1;
    ptr.y = -(e.clientY/innerHeight)*2+1;
    ray.setFromCamera(ptr, camera);
    camera.updateMatrixWorld(true);   // 射线依赖最新世界矩阵（flyTo 结束时可能滞后）
    const nhit = ray.intersectObjects(nationCityHits, false);
    if (nhit.length) nationEnterCity(nhit[0].object.userData.cityId);
    else window.__nationMiss = (window.__nationMiss || 0) + 1;   // 诊断：未命中计数
    return;
  }
  if (annoMode && world && world.city.kind !== 'bridges'){
    ptr.x = (e.clientX/innerWidth)*2-1;
    ptr.y = -(e.clientY/innerHeight)*2+1;
    ray.setFromCamera(ptr, camera);
    const ground = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
    const pt = new THREE.Vector3();
    if (ray.ray.intersectPlane(ground, pt)){
      annoPending = reverseProject(pt.x, pt.z);
      $('anno-name').focus();
      perfToast('📍 位置已选择 · 输入名称后保存');
    }
    return;
  }
  ptr.x = (e.clientX/innerWidth)*2-1;
  ptr.y = -(e.clientY/innerHeight)*2+1;
  ray.setFromCamera(ptr, camera);
  const meshes = Object.values(lineStMeta).map(x => x.mesh).filter(Boolean)
    .concat(world.tombMeshes || [])
    .concat(trainsMesh && trainsMesh.visible ? [trainsMesh] : [])
    .concat((world.annoPins || []).map(x => x.grp));
  const hit = ray.intersectObjects(meshes, false);
  if (hit.length && hit[0].object === trainsMesh && hit[0].instanceId !== undefined){
    showTrainCard(trains[hit[0].instanceId]);
    return;
  }
  {
    let annoHit = null;
    for (const h of hit){
      let o = h.object;
      while (o && !(o.userData && o.userData.annoId !== undefined)) o = o.parent;
      if (o){ annoHit = o.userData.annoId; break; }
    }
    if (annoHit !== null){
      const item = getAnnoList().find(x => x.id === annoHit);
      if (item){
        const pos = project(item.lng, item.lat, world.origin);
        const target = new THREE.Vector3(pos.x, 0, pos.z);
        const dist = Math.max(30, (world.lineSize || world.size || 200) * 0.14);
        const dir = new THREE.Vector3(0.15, 0.58, 0.92).normalize();
        state.flyTo = { from: camera.position.clone(), to: target.clone().addScaledVector(dir, dist),
          fromT: controls.target.clone(), toT: target, t: 0 };
        perfToast('📍 ' + item.name + (item.note ? ' · ' + item.note : ''));
      }
      return;
    }
  }
  if (hit.length && hit[0].object.userData.tombIdx !== undefined){
    showTombCard(world.tombItems[hit[0].object.userData.tombIdx]);
    return;
  }
  if (hit.length){
    const h0 = hit[0];
    const lineId = Object.keys(lineStMeta).find(k => lineStMeta[k].mesh === h0.object);
    const sm = lineStMeta[lineId];
    if (sm && h0.instanceId !== undefined){
      const m = sm.meta[h0.instanceId];
      if (m){
        const line = world.lines[m.lineIdx];
        if (line) focusStation(line, m.stIdx);
      }
    }
  }
});
canvas.addEventListener('wheel', () => { if (state.screensaver) exitScreensaver(); controls.autoRotate = false; stopCruise(); resetIdle(); }, { passive: true });
document.addEventListener('keydown', () => { resetIdle(); }, { passive: true });

$('sel-city').addEventListener('change', e => {
  if (nationMode) exitNation(false);
  const c = METRO_DATA.cities.find(x => x.id === e.target.value);
  if (!c) return;   // 无效值防御（URL 篡改/数据异常时静默忽略）
  try {
    let rc = JSON.parse(localStorage.getItem('metro3d-recent') || '[]');
    rc = [c.id, ...rc.filter(x => x !== c.id)].slice(0, 3);
    localStorage.setItem('metro3d-recent', JSON.stringify(rc)); } catch(err){ __recErr('recent.save', err && err.message, 'localStorage'); }
  state.cityId = c.id; state.focusLineId = '__all__';
  document.getElementById('info-card').classList.remove('show');
  populateSelectors(); rebuild();
});
$('sel-line').addEventListener('change', e => {
  const v = e.target.value;
  if (v.startsWith('bridge-')){
    state.focusLineId = '__all__';
    focusBridge(+v.split('-')[1]);
    return;
  }
  state.focusLineId = v;
  rebuild();
});

function rebuild(keepCamera){
  stopCruise();
  buildWorld(!keepCamera);
}

let vscaleTimer = null;
$('vscale').addEventListener('input', e => {
  const v = +e.target.value;
  $('vscale-val').textContent = v + '×';
  V_SCALE = v * H_SCALE;
  clearTimeout(vscaleTimer);
  vscaleTimer = setTimeout(() => rebuild(true), 160);
});
$('btn-depth-color').addEventListener('click', e => {
  state.depthColor = !state.depthColor;
  e.currentTarget.classList.toggle('on', state.depthColor);
  rebuild(true);
});
$('btn-labels').addEventListener('click', e => {
  state.labels = !state.labels;
  e.currentTarget.classList.toggle('on', state.labels);
  allLabels.forEach(l => l.visible = false);
});
$('btn-strata').addEventListener('click', e => {
  state.strata = !state.strata;
  e.currentTarget.classList.toggle('on', state.strata);
  world.strataGroup.visible = state.strata;
});
$('btn-trains').addEventListener('click', e => {
  state.trains = !state.trains;
  e.currentTarget.classList.toggle('on', state.trains);
  if (trainsMesh) trainsMesh.visible = state.trains && trains.length > 0;
});

/* ---------------- 线网生长时间轴 ---------------- */
let timelineOn = false;
function applyTimeline(year){
  state.timeline = year;
  let on = 0, tot = 0, stOn = 0, stTot = 0;
  lineGroups.forEach(lg => {
    const opened = lg.line.opened || 3000;
    const show = !year || opened <= year;
    lg.group.visible = show;
    tot++; if (show) on++;
    stTot += lg.line.stations.length; if (show) stOn += lg.line.stations.length;
  });
  (world.railwayGroups || []).forEach(rg => { rg.grp.visible = !year || rg.year <= year; });
  $('tl-year').textContent = (year || 2026) + ' 年';
  const tc = $('tl-cnt');
  if (tc) tc.textContent = year ? `${on}线/${stOn}站` : '';
}
$('btn-timeline').addEventListener('click', e => {
  timelineOn = !timelineOn;
  e.currentTarget.classList.toggle('on', timelineOn);
  $('tl-row').style.display = timelineOn ? 'flex' : 'none';
  if (timelineOn){ applyTimeline(+$('tl-slider').value); }
  else { applyTimeline(null); }
});
$('tl-slider').addEventListener('input', e => {
  applyTimeline(+e.target.value);
});
$('btn-reset').addEventListener('click', () => {
  stopCruise();
  fitAll(false);
  $('info-card').classList.remove('show');
  state.selectedIdx = -1;
});
$('ic-close').addEventListener('click', () => $('info-card').classList.remove('show'));
/* 站点面板折叠（桌面默认收起，避免遮挡三维视图；移动端保持底部抽屉） */
const isMobile = () => window.matchMedia('(max-width: 860px)').matches;
function setListCollapsed(v){
  const panel = $('panel-list'), floatBtn = $('btn-list-float');
  if (isMobile()){
    panel.classList.remove('collapsed');
    panel.classList.toggle('show', !v);
    floatBtn.style.display = 'none';
  } else {
    panel.classList.remove('show');
    panel.classList.toggle('collapsed', v);
    floatBtn.style.display = v ? 'flex' : 'none';
  }
}
$('btn-list-collapse').addEventListener('click', () => setListCollapsed(true));
$('btn-list-float').addEventListener('click', () => setListCollapsed(false));
addEventListener('resize', () => setListCollapsed(state.listCollapsed));

$('btn-list-toggle').addEventListener('click', () => {
  const open = !$('panel-list').classList.contains('show');
  setListCollapsed(!open);
  $('panel-ctrl').classList.remove('show');
});
$('btn-ctrl-toggle').addEventListener('click', () => {
  $('panel-ctrl').classList.toggle('show');
  $('panel-list').classList.remove('show');
});

/* 沿线巡航（聚焦线路） */
function stopCruise(){
  if (state.cruise){
    state.cruise = null;
    $('btn-cruise').textContent = '▶ 沿线巡航';
    controls.enabled = true;
  }
}
$('btn-cruise').addEventListener('click', () => {
  if (state.cruise){ stopCruise(); return; }
  if (!world.lines.length) return;   // 桥梁模式无线路可巡航
  if (state.focusIdx < 0){
    state.focusLineId = world.lines[0].id; $('sel-line').value = state.focusLineId;
    rebuild(true);
  }
  const lg = lineGroups[state.focusIdx];
  if (!lg){ stopCruise(); return; }
  controls.enabled = false;
  controls.autoRotate = false;
  state.cruise = { u: 0, curve: lg.group.userData.curve };
  $('btn-cruise').textContent = '⏸ 停止巡航';
  $('info-card').classList.remove('show');
});

/* ---------------- 城市湖泊（多边形水面，如玄武湖/西湖） ---------------- */
function buildCityLakes(city, origin, container){
  if (!city.lakes || !city.lakes.length) return;
  city.lakes.forEach(lk => {
    const pts = lk.points.map(([lng, lat]) => project(lng, lat, origin));
    const shape = new THREE.Shape(pts.map(p => new THREE.Vector2(p.x, p.z)));
    const mesh = new THREE.Mesh(new THREE.ShapeGeometry(shape),
      new THREE.MeshBasicMaterial({ color: lk.color || 0x1a6492, transparent: true,
        opacity: .6, side: THREE.DoubleSide, depthWrite: false }));
    mesh.rotation.x = -Math.PI / 2;
    mesh.renderOrder = 1;
    container.add(mesh);
    let cx = 0, cz = 0;
    pts.forEach(p => { cx += p.x; cz += p.z; });
    cx /= pts.length; cz /= pts.length;
    const lb = makeLabel(lk.name, lk.desc || '', '#8fd4ff');
    lb.position.set(cx, 2.2, cz);
    lb.scale.set(16, 5, 1);
    lb.userData.alwaysVisible = true;
    container.add(lb);
    allLabels.push(lb);
    globalLabelInfo.push({ lake: true });
  });
}

/* ---------------- 朝代着色（古墓群按时代分色） ---------------- */
const ERA_STYLES = [
  { key: '东汉', test: /东汉|汉/, color: 0xc89a4a, label: '东汉' },     // 赤金
  { key: '曹魏', test: /曹魏|魏文帝|三国/, color: 0x9a6ad8, label: '曹魏' }, // 紫
  { key: '西晋', test: /西晋|晋武/, color: 0x6a8ad8, label: '西晋' },     // 靛蓝
  { key: '北魏', test: /北魏/, color: 0xd8606a, label: '北魏' },          // 朱红
  { key: '唐',   test: /唐/, color: 0x4aa8d8, label: '唐' },              // 天青
  { key: '民国', test: /民国/, color: 0x5aa87a, label: '民国' },          // 松绿
  { key: '明清', test: /明|清/, color: 0x8a8a96, label: '明清' },          // 青灰
];
function eraStyle(era){
  const s = String(era || '');
  for (const st of ERA_STYLES) if (st.test.test(s)) return st;
  return ERA_STYLES[ERA_STYLES.length - 1];
}

/* ---------------- 邙山古墓群（帝王将相·名人墓葬点） ---------------- */
function buildCityTombs(city, origin, container){
  world.tombMeshes = [];
  world.tombItems = [];
  if (!city.tombs || !city.tombs.items) return;
  city.tombs.items.forEach((t, idx) => {
    const p = project(t.lng, t.lat, origin);
    const isEmperor = t.role === '帝王';
    const dW = Math.max(1.4, t.moundD * 0.03);   // 封土直径（视觉最小 1.4u）
    const hH = Math.max(0.5, t.moundH * 0.08);   // 封土高（与山体 8× 夸张一致）
    const era = eraStyle(t.era);
    const mound = new THREE.Mesh(
      new THREE.SphereGeometry(dW / 2, 12, 8, 0, Math.PI * 2, 0, Math.PI / 2),
      new THREE.MeshStandardMaterial({ color: era.color, roughness: 1, flatShading: true }));
    mound.position.set(p.x, 0, p.z);
    mound.scale.y = hH / (dW / 2);
    mound.userData.tombIdx = idx;
    const grp = new THREE.Group();
    grp.add(mound);
    // 墓碑
    const stele = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.8, 0.38),
      new THREE.MeshStandardMaterial({ color: 0xcfd6de, roughness: .5 }));
    stele.position.set(p.x, 0.4, p.z + dW / 2 + 0.3);
    grp.add(stele);
    // 标签：帝王常显，名人近景显
    const lb = makeLabel(t.name.split(' · ')[0], era.label + ' · ' + t.era.split(' · ')[1], '#' + era.color.toString(16).padStart(6, '0'));
    lb.position.set(p.x, hH + 4.5, p.z);
    lb.scale.set(isEmperor ? 16 : 12, isEmperor ? 5.2 : 4, 1);
    lb.userData.alwaysVisible = isEmperor;
    grp.add(lb); allLabels.push(lb); globalLabelInfo.push({ tomb: true });
    container.add(grp);
    world.tombMeshes.push(mound);
    world.tombItems.push(t);
  });
}

/* ---------------- 交通枢纽（机场，金色菱形 + 与地铁站连线） ---------------- */
function buildCityAirports(city, origin, container){
  if (!city.airports || !city.airports.length) return;
  city.airports.forEach((ap, idx0) => {
    const p = project(ap.lng, ap.lat, origin);
    const grp = new THREE.Group();
    // 金色菱形（旋转 45° 的方块 + 跑道标记）
    const diamond = new THREE.Mesh(new THREE.BoxGeometry(2.0, 0.5, 2.0),
      new THREE.MeshStandardMaterial({ color: 0xE8B44A, emissive: 0x6a4a10, emissiveIntensity: .8, roughness: .4 }));
    diamond.rotation.y = Math.PI / 4;
    diamond.position.set(p.x, 0.6, p.z);
    grp.add(diamond);
    const runway = new THREE.Mesh(new THREE.BoxGeometry(2.6, 0.2, 0.4),
      new THREE.MeshStandardMaterial({ color: 0x8a97a8, roughness: .7 }));
    runway.position.set(p.x, 1.0, p.z);
    grp.add(runway);
    // IATA 标签（金色大字 + 机场名）
    const lb = makeLabel(ap.iata || ap.name, ap.note || ap.name, '#E8B44A');
    lb.position.set(p.x, 5, p.z);
    lb.scale.set(14, 4.4, 1);
    lb.userData.alwaysVisible = true;
    grp.add(lb);
    allLabels.push(lb);
    globalLabelInfo.push({ airport: true });
    // 与最近地铁站连线（金色细线，按 2D 距离找最近站）
    let best = null, bd = Infinity;
    (city.lines || []).forEach(l => l.stations.forEach(s => {
      const d = Math.hypot(s.lng - ap.lng, s.lat - ap.lat);
      if (d < bd){ bd = d; best = s; }
    }));
    if (best && bd < 0.35){
      const sp = project(best.lng, best.lat, origin);
      grp.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(
        [new THREE.Vector3(p.x, 1, p.z), new THREE.Vector3(sp.x, 1, sp.z)]),
        new THREE.LineBasicMaterial({ color: 0xE8B44A, transparent: true, opacity: .5 })));
    }
    // 大飞机标志：绕机场盘旋（白色机身金色鼻锥，翼展 7.2 ≈ 翼展 720m 视觉）
    const plane = makePlaneMesh();
    plane.position.set(p.x, 13, p.z);
    container.add(plane);
    __airportPlanes.push({ grp: plane, cx: p.x, cz: p.z, alt: 13,
      angle: Math.random() * Math.PI * 2, R: 11 + (idx0 % 3) * 2.5, speed: 0.32 + (idx0 % 2) * 0.08 });
    container.add(grp);
  });
}

/* ---------------- 机场飞机（盘旋的大飞机标志） ---------------- */
function makePlaneMesh(){
  const grp = new THREE.Group();
  const body = new THREE.MeshStandardMaterial({ color: 0xf2f6fa, emissive: 0x8a97a8,
    emissiveIntensity: .55, roughness: .35, metalness: .35 });
  const gold = new THREE.MeshStandardMaterial({ color: 0xE8B44A, emissive: 0x6a4a10,
    emissiveIntensity: .75, roughness: .4 });
  // 机身（沿 +Z，机头在 +Z 端）
  const fus = new THREE.Mesh(new THREE.CapsuleGeometry(0.38, 3.0, 3, 8), body);
  fus.rotation.x = Math.PI / 2;
  fus.position.z = -0.4;
  grp.add(fus);
  // 金色机头
  const nose = new THREE.Mesh(new THREE.SphereGeometry(0.34, 8, 8), gold);
  nose.position.z = -2.15;
  grp.add(nose);
  // 主翼（后掠）
  const wing = new THREE.Mesh(new THREE.BoxGeometry(7.2, 0.14, 1.5), body);
  wing.position.set(0, -0.1, 0.2);
  grp.add(wing);
  // 尾翼（垂直 + 水平）
  const vt = new THREE.Mesh(new THREE.BoxGeometry(0.12, 1.0, 0.9), gold);
  vt.position.set(0, 0.55, 1.9);
  grp.add(vt);
  const ht = new THREE.Mesh(new THREE.BoxGeometry(2.5, 0.1, 0.65), body);
  ht.position.set(0, 0.12, 1.9);
  grp.add(ht);
  // 两台翼下引擎
  [-1, 1].forEach(s => {
    const eng = new THREE.Mesh(new THREE.CapsuleGeometry(0.22, 0.7, 3, 6), gold);
    eng.rotation.x = Math.PI / 2;
    eng.position.set(s * 2.1, -0.28, -0.35);
    grp.add(eng);
  });
  return grp;
}
let __airportPlanes = [];
function updateAirportPlanes(dt){
  for (const p of __airportPlanes){
    if (__reduceMotion) continue;   // 减少动态：飞机悬停不动
  p.angle -= dt * p.speed;   // 俯视逆时针盘旋
    const x = p.cx + Math.cos(p.angle) * p.R;
    const z = p.cz + Math.sin(p.angle) * p.R;
    const nx = p.cx + Math.cos(p.angle - 0.12) * p.R;
    const nz = p.cz + Math.sin(p.angle - 0.12) * p.R;
    p.grp.position.set(x, p.alt, z);
    p.grp.lookAt(nx, p.alt, nz);
    p.grp.rotateY(Math.PI);   // 模型机头 +Z → 对齐飞行方向
  }
}

/* ---------------- 我的标注（用户自定义 pin，本地存储） ---------------- */
function getAnnoList(){
  try { return JSON.parse(localStorage.getItem('metro3d-annotations') || '[]'); } catch(e){ return []; }
}
function saveAnnoList(list){
  try { localStorage.setItem('metro3d-annotations', JSON.stringify(list)); } catch(e){ __recErr('anno.save', e && e.message, 'localStorage'); }
}
function makeAnnoPin(item, origin){
  const p = project(item.lng, item.lat, origin);
  const grp = new THREE.Group();
  const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.12, 6, 6),
    new THREE.MeshStandardMaterial({ color: 0xE8B44A, emissive: 0x6a4a10, emissiveIntensity: .8 }));
  pole.position.set(p.x, 3, p.z);
  grp.add(pole);
  const flag = new THREE.Mesh(new THREE.BoxGeometry(1.6, 0.8, 0.08),
    new THREE.MeshStandardMaterial({ color: 0xE8B44A, emissive: 0x8a6a10, emissiveIntensity: .9, roughness: .4 }));
  flag.position.set(p.x + 0.8, 5.2, p.z);
  grp.add(flag);
  const ring = new THREE.Mesh(new THREE.RingGeometry(0.9, 1.3, 24),
    new THREE.MeshBasicMaterial({ color: 0xE8B44A, transparent: true, opacity: .5, side: THREE.DoubleSide, depthWrite: false }));
  ring.rotation.x = -Math.PI / 2;
  ring.position.set(p.x, 0.3, p.z);
  grp.add(ring);
  const lb = makeLabel(item.name, '我的标注', '#E8B44A');
  lb.position.set(p.x, 8.5, p.z);
  lb.scale.set(13, 4.2, 1);
  grp.add(lb);
  allLabels.push(lb);
  globalLabelInfo.push({ anno: true });
  return grp;
}
function buildCityAnnotations(city, origin, container){
  world.annoPins = [];
  const list = getAnnoList().filter(x => x.cityId === city.id);
  list.forEach(item => {
    const pin = makeAnnoPin(item, origin);
    container.add(pin);
    world.annoPins.push({ grp: pin, item });
  });
}
function updateAnnoPins(dt){}   // 预留：标注为静态

/* ---------------- 城市铁路（高铁轨迹，与地铁视觉区分） ---------------- */
function buildCityRailways(city, origin, container){
  world.railwayGroups = [];
  if (!city.railways || !city.railways.length) return;
  city.railways.forEach(rw => {
    const grp = new THREE.Group();
    const pts = rw.points.map(([lng, lat]) => project(lng, lat, origin));
    const curve = new THREE.CatmullRomCurve3(pts, false, 'centripetal');
    // 细银白轨道（radius 0.85 ≪ 地铁 1.25，金属质感）
    const building = rw.status === 'building';
    const tube = new THREE.Mesh(
      new THREE.TubeGeometry(curve, Math.max(120, Math.min(400, pts.length * 4)), building ? 0.42 : 0.5, 6, false),
      building
        ? new THREE.MeshBasicMaterial({ color: 0x9aa8b8, transparent: true, opacity: .38 })
        : (() => { const m = new THREE.MeshStandardMaterial({ color: 0xdfe6ee, emissive: 0x8a97a8, emissiveIntensity: .55, roughness: .35, metalness: .5 }); m.userData.themeRole = 'rail'; return m; })());
    grp.add(tube);
    (rw.stations || []).forEach(st => {
      const p = project(st.lng, st.lat, origin);
      const box = new THREE.Mesh(new THREE.BoxGeometry(1.1, 1.1, 1.1),
        building
          ? new THREE.MeshStandardMaterial({ color: 0x8a97a8, transparent: true, opacity: .5, roughness: .6 })
          : new THREE.MeshStandardMaterial({ color: 0xE8B44A, emissive: 0x6a4a10, emissiveIntensity: .8, roughness: .4 }));
      box.position.set(p.x, 0.8, p.z);
      grp.add(box);
      const lb = makeLabel(st.name, rw.name, '#E8B44A');
      lb.position.set(p.x, 9, p.z);
      lb.scale.set(18, 5.8, 1);
      lb.userData.alwaysVisible = true;
      grp.add(lb); allLabels.push(lb); globalLabelInfo.push({ railway: true });
      // 换乘连线（数据 transfer 字段指明地铁站名）
      if (st.transfer){
        const m = (city.lines || []).flatMap(l => l.stations.map(s => ({ s }))).find(x => x.s.name === st.transfer);
        if (m){
          const mp = project(m.s.lng, m.s.lat, origin);
          grp.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(
            [new THREE.Vector3(p.x, 1, p.z), new THREE.Vector3(mp.x, 1, mp.z)]),
            new THREE.LineBasicMaterial({ color: 0xE8B44A, transparent: true, opacity: .6 })));
        }
      }
    });
    const mid = curve.getPointAt(0.62);
    const lb2 = makeLabel(rw.name, rw.desc || '', '#cfd8e3');
    lb2.position.set(mid.x, 6, mid.z);
    lb2.scale.set(22, 7, 1);
    lb2.userData.alwaysVisible = true;
    grp.add(lb2); allLabels.push(lb2); globalLabelInfo.push({ railway: true });
    container.add(grp);
    world.railwayGroups.push({ grp, curve, year: rw.year || 1900, railway: rw });
  });
}

/* ---------------- 场景主题（浅色/深色调色板，随 UI 主题联动） ---------------- */
