/* ---------------- 深链：?city=shanghai&line=sh-9 ---------------- */
(function applyDeepLink(){
  try {
    const qp = new URLSearchParams(location.search);
    const cid = qp.get('city');
    if (cid && METRO_DATA.cities.some(c => c.id === cid)) state.cityId = cid;
    const ln = qp.get('line');
    if (ln) state.focusLineId = ln;
    const cam = qp.get('cam');
    if (cam){
      const v = cam.split(',').map(Number);
      if (v.length === 6 && v.every(x => Number.isFinite(x))){ window.__initCam = v; state.__camTouched = true; }
    }
    const th = qp.get('theme');
    if (th === 'night' || th === 'light') state.__initTheme = th;
    const ly = qp.get('layers');
    if (ly !== null){
      const on = ly.split(',').filter(Boolean);
      ['landmarks', 'terrain', 'tombs', 'lakes', 'railways'].forEach(k => {
        state.layers[k] = on.includes(k);
      });
    }
  } catch(e){ __recErr('deeplink.layers', e && e.message, 'URLSearchParams'); }
})();

function syncUrl(){
  try {
    const u = new URL(location.href);
    if (state.cityId) u.searchParams.set('city', state.cityId);
    if (state.focusLineId && state.focusLineId !== '__all__') u.searchParams.set('line', state.focusLineId);
    else u.searchParams.delete('line');
    if (state.__camTouched && camera){
      const p = camera.position, t = controls.target;
      u.searchParams.set('cam', [p.x, p.y, p.z, t.x, t.y, t.z].map(v => Math.round(v * 10) / 10).join(','));
    } else u.searchParams.delete('cam');
    // 主题 / 图层（非默认才写入，保持 URL 简洁）
    if (state.night) u.searchParams.set('theme', 'night');
    else if (document.documentElement.getAttribute('data-theme') === 'light') u.searchParams.set('theme', 'light');
    else u.searchParams.delete('theme');
    // 🌌 星图深链：nationMode 为真、或深链意图尚未消费（__wantNation）时都保留参数，
    // 否则启动期 syncUrl 会抢在 enterNation(900ms) 之前把参数抹掉 → 深链失效。
    if (nationMode || (__wantNation && !__wantNationDone)) u.searchParams.set('nation', '1');
    else u.searchParams.delete('nation');
    const L = state.layers, Ld = { landmarks: true, terrain: true, tombs: true, lakes: true, railways: true };
    if (Object.keys(Ld).some(k => !!L[k] !== Ld[k])){
      u.searchParams.set('layers', Object.keys(Ld).filter(k => L[k]).join(','));
    } else u.searchParams.delete('layers');
    if (u.search !== location.search) history.replaceState(null, '', u.toString());
  } catch(e){ __recErr('syncUrl', e && e.message, 'history'); }
}

