/* ---------------- 站点搜索 ---------------- */
const STATION_INDEX = [];
(function buildSearchIndex(){
  METRO_DATA.cities.forEach(c => {
    if (c.kind === 'bridges'){
      (c.bridges || []).forEach((b, i) => STATION_INDEX.push({
        type: 'bridge', name: b.name, cityId: c.id, cityName: c.name,
        i, sub: `${b.cat} · ${b.lenKm} km`, color: b.color }));
      return;
    }
    const seen = new Set();   // 同城同名站（换乘）只收录一次
    (c.lines || []).forEach((l, li) => {
      l.stations.forEach((s, si) => {
        if (seen.has(s.name)) return; seen.add(s.name);
        const dep = s.type === 'elevated' ? `+${s.height}m` : s.type === 'ground' ? '地面' : `${s.depth}m`;
        STATION_INDEX.push({ type: 'st', name: s.name, cityId: c.id, cityName: c.name,
          li, si, sub: `${l.name} · ${dep}`, color: l.color });
      });
    });
    if (c.tombs) c.tombs.items.forEach(t => STATION_INDEX.push({
      type: 'tomb', name: t.name, cityId: c.id, cityName: c.name,
      sub: `${t.role}墓 · ${t.era.split(' · ')[0]}`, color: '#d8b878' }));
    if (c.lakes) c.lakes.forEach(lk => STATION_INDEX.push({
      type: 'lake', name: lk.name, cityId: c.id, cityName: c.name,
      sub: lk.desc || '湖泊水域', color: '#8fd4ff' }));
    if (c.airports) c.airports.forEach(air => STATION_INDEX.push({
      type: 'airport', name: air.name, cityId: c.id, cityName: c.name,
      sub: `${air.iata} · ${air.note || ''}`, color: '#E8B44A' }));
  });
})();

function isSubseq(q, n){
  if (q.length > n.length) return false;
  let i = 0;
  for (const ch of n){ if (ch === q[i]) i++; if (i === q.length) return true; }
  return i === q.length;
}

function searchStations(q){
  q = q.trim().toLowerCase();
  if (!q) return [];
  const scored = [];
  for (const e of STATION_INDEX){
    const n = e.name.toLowerCase();
    let sc = -1;
    if (n === q) sc = 0;
    else if (n.startsWith(q)) sc = 1;
    else if (n.includes(q)) sc = 2;
    else if (isSubseq(q, n)) sc = 3;          // 子序列："北郊机场"命中"北郊国际机场"
    else if ((e.sub || '').toLowerCase().includes(q)) sc = 4;
    if (sc >= 0) scored.push({ e, sc });
  }
  scored.sort((a, b) => a.sc - b.sc || a.e.name.length - b.e.name.length);
  return scored.slice(0, 12).map(x => x.e);
}

let searchCur = [], searchAct = -1, searchTimer = null;
function searchDo(q){
  const drop = $('search-drop');
  searchCur = searchStations(q);
  searchAct = -1;
  if (!searchCur.length){
    drop.innerHTML = q.trim() ? '<div class="empty">未找到匹配站点</div>' : '';
    drop.style.display = q.trim() ? 'block' : 'none';
    return;
  }
  drop.innerHTML = searchCur.map((e, i) =>
    `<div class="sr" data-i="${i}"><i style="background:${e.color}"></i><b>${esc(e.name)}</b><span>${esc(e.sub || '')}</span><span class="ct">${esc(e.cityName)}</span></div>`).join('');
  drop.style.display = 'block';
  [...drop.querySelectorAll('.sr')].forEach(el => el.addEventListener('mousedown', ev => {
    ev.preventDefault();
    searchGo(searchCur[+el.dataset.i]);
  }));
}
function searchGo(e){
  $('search-drop').style.display = 'none';
  $('st-search').value = ''; $('st-search').blur();
  if (e.type === 'bridge'){
    state.cityId = 'bridges';
    populateSelectors();
    $('sel-city').value = 'bridges';
    $('sel-line').value = 'bridge-' + e.i;
    rebuild();
    focusBridge(e.i);
    return;
  }
  if (e.type === 'airport'){
    if (state.cityId !== e.cityId){
      state.cityId = e.cityId;
      populateSelectors();
      rebuild();
    }
    const city = METRO_DATA.cities.find(x => x.id === e.cityId);
    const air = (city.airports || []).find(x => x.name === e.name);
    if (air){
      const pos = project(air.lng, air.lat, world.origin);
      const target = new THREE.Vector3(pos.x, 0, pos.z);
      const dist = Math.max(40, (world.lineSize || world.size || 200) * 0.16);
      const dir = new THREE.Vector3(0.15, 0.58, 0.92).normalize();
      state.flyTo = { from: camera.position.clone(), to: target.clone().addScaledVector(dir, dist),
        fromT: controls.target.clone(), toT: target, t: 0 };
    }
    return;
  }
  if (e.type === 'lake'){
    if (state.cityId !== e.cityId){
      state.cityId = e.cityId;
      populateSelectors();
      rebuild();
    }
    const city = METRO_DATA.cities.find(x => x.id === e.cityId);
    const lk = (city.lakes || []).find(l => l.name === e.name);
    if (lk){
      const pts = lk.points.map(([lng, lat]) => project(lng, lat, world.origin));
      let cx = 0, cz = 0; pts.forEach(p => { cx += p.x; cz += p.z; });
      cx /= pts.length; cz /= pts.length;
      const target = new THREE.Vector3(cx, 0, cz);
      const dist = Math.max(30, (world.lineSize || world.size || 200) * 0.18);
      const dir = new THREE.Vector3(0.15, 0.58, 0.92).normalize();
      state.flyTo = { from: camera.position.clone(), to: target.clone().addScaledVector(dir, dist),
        fromT: controls.target.clone(), toT: target, t: 0 };
    }
    return;
  }
  if (e.type === 'tomb'){
    if (state.cityId !== e.cityId){
      state.cityId = e.cityId;
      populateSelectors();
      rebuild();
    }
    const item = (METRO_DATA.cities.find(x => x.id === e.cityId).tombs || {}).items || [];
    const item0 = item.find(t => t.name === e.name);
    if (item0) showTombCard(item0);
    return;
  }
  if (state.cityId !== e.cityId){
    state.cityId = e.cityId;
    populateSelectors();
    rebuild();
  }
  const line = METRO_DATA.cities.find(x => x.id === e.cityId).lines[e.li];
  if (line) focusStation(line, e.si);
}
$('st-search').addEventListener('input', e => {
  clearTimeout(searchTimer);
  const q = e.target.value;
  searchTimer = setTimeout(() => searchDo(q), 120);
});
$('st-search').addEventListener('keydown', e => {
  const rows = [...$('search-drop').querySelectorAll('.sr')];
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp'){
    if (!rows.length) return;
    e.preventDefault();
    searchAct = e.key === 'ArrowDown' ? Math.min(rows.length - 1, searchAct + 1) : Math.max(0, searchAct - 1);
    rows.forEach((r, i) => r.classList.toggle('act', i === searchAct));
    rows[searchAct].scrollIntoView({ block: 'nearest' });
  } else if (e.key === 'Enter'){
    if (rows.length) searchGo(searchCur[Math.max(0, searchAct)]);
  } else if (e.key === 'Escape'){
    $('search-drop').style.display = 'none';
    e.target.blur();
  }
});
document.addEventListener('pointerdown', e => {
  if (!e.target.closest('.search-row')) $('search-drop').style.display = 'none';
});
