// 视口跨断点变化时，移动端自动折叠顶部详情（除非用户手动展开过）
(function watchViewport(){
  const mq = window.matchMedia('(max-width: 860px)');
  const apply = () => {
    const el = document.getElementById('panel-title');
    if (mq.matches && !state.titleUserToggled){
      el.classList.add('collapsed');
      document.getElementById('btn-title-toggle').textContent = '▾';
    }
  };
  if (mq.addEventListener) mq.addEventListener('change', apply);
  else if (mq.addListener) mq.addListener(apply);
  // 首次进入移动端也应用
  apply();
})();

// 开场（深链带 cam 时跳过开场动画，直接还原视角）
let introFrom, introTo;
{
  if (window.__initCam){
    const [px, py, pz, tx, ty, tz] = window.__initCam;
    camera.position.set(px, py, pz);
    controls.target.set(tx, ty, tz);
    controls.update();
  } else {
    if (!__reduceMotion){
    const dir = new THREE.Vector3(0.15, 0.55, 0.95).normalize();
    introTo = camera.position.clone();
    introFrom = world.center.clone().addScaledVector(dir, world.size * 2.2);
    introFrom.y = world.size * 1.05;
    camera.position.copy(introFrom);
    controls.enabled = false;
    introT = 0;
    }
  }
}

addEventListener('resize', () => {
  camera.aspect = innerWidth/innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

setTimeout(() => { if ('serviceWorker' in navigator && location.protocol.startsWith('http')){
  navigator.serviceWorker.register('./sw.js').catch(() => {});
}

$('hint').style.opacity = '0'; }, 9000);

animate();
setInterval(() => { if (document.hidden || __appPaused || performance.now() - __lastRaf > 300) return; renderFrame(); }, 120);
document.getElementById('loading').classList.add('hide');

document.getElementById('loading').classList.add('hide');

/* ---------------- 海报模式（?poster=1&city=shanghai&view=core） ----------------
 * 用于 8K 出图：隐藏全部 UI、按预设机位取景、可选水印。
 * 不影响常规访问（无参数时行为完全不变）。
 */
(function posterMode(){
  const qp = new URLSearchParams(location.search);
  if (qp.get('poster') !== '1') return;
  const hide = ['panel-title','panel-ctrl','panel-list','info-card','btn-list-toggle','btn-ctrl-toggle','hint','note'];
  hide.forEach(id => { const e = document.getElementById(id); if (e) e.style.display = 'none'; });

  const cityId = qp.get('city') || 'shanghai';
  const c = METRO_DATA.cities.find(x => x.id === cityId);
  if (c){
    state.cityId = cityId;
    state.focusLineId = '__all__';
    populateSelectors();
    rebuild();
  }
  controls.autoRotate = false;
  const view = qp.get('view') || 'overview';
  const w = world;
  const THREE_ = window.THREE;

  if (w && w.city && w.city.kind === 'bridges'){
    // 桥梁模式：聚焦指定桥
    const bi = +(qp.get('bridge') || 0);
    if (w.city.bridges && w.city.bridges[bi]) focusBridge(bi);
  } else if (w){
    let target = w.center.clone(), dist = w.size * 0.85;
    let dir = new THREE_.Vector3(0.15, 0.55, 0.95).normalize();
    const kx = 111320 * Math.cos(w.origin.lat * Math.PI / 180) * 0.01;
    const kz = 110540 * 0.01;

    if (view === 'top'){            // 高俯视，地图感
      target.y = -6; dist = w.size * 0.78;
      dir = new THREE_.Vector3(0.02, 0.985, 0.17).normalize();
    } else if (view === 'core'){    // 核心区特写
      const lng = +(qp.get('lng') || 121.478), lat = +(qp.get('lat') || 31.232);
      target = new THREE_.Vector3((lng - w.origin.lng) * kx, -14, -(lat - w.origin.lat) * kz);
      dist = +(qp.get('dist') || 330);
      dir = new THREE_.Vector3(0.30, 0.58, 0.76).normalize();
    } else if (view === 'river'){   // 沿江侧视
      const lng = +(qp.get('lng') || 121.500), lat = +(qp.get('lat') || 31.235);
      target = new THREE_.Vector3((lng - w.origin.lng) * kx, -8, -(lat - w.origin.lat) * kz);
      dist = +(qp.get('dist') || 300);
      dir = new THREE_.Vector3(0.62, 0.34, 0.70).normalize();
    } else if (view === 'wide'){    // 更远全景
      target.y = -20; dist = w.size * 1.05;
      dir = new THREE_.Vector3(0.18, 0.62, 0.86).normalize();
    }
    controls.target.copy(target);
    camera.position.copy(target.clone().addScaledVector(dir, dist));
    camera.lookAt(target);
    controls.update();
    state.flyTo = null;      // 覆盖 rebuild 触发的相机飞行
    state.cruise = null;
    controls.autoRotate = false;
  }

  // 水印
  const wmText = qp.get('wm');
  if (wmText !== '0'){
    const cityName = (world && world.city && world.city.name) || '上海';
    const lineCnt = (world && world.lines) ? world.lines.length : 0;
    const stCnt = (world && world.lines) ? world.lines.reduce((a,l)=>a+l.stations.length,0) : 0;
    const wm = document.createElement('div');
    wm.id = 'poster-wm';
    // 安全（v2.2.0）：wmsize 来自 URL，必须数字化后再插值——否则可注入 HTML（反射型 XSS）
    const big = Math.min(200, Math.max(8, parseInt(qp.get('wmsize'), 10) || 52));
    wm.innerHTML = `<div style="font-size:${big}px;font-weight:700;letter-spacing:7px;color:#eaf4ff;line-height:1.18;text-shadow:0 6px 32px rgba(0,0,0,.9)">${esc(cityName)}轨道交通 · 地下三维线网</div>`
      + `<div style="font-size:${Math.round(+big*0.42)}px;margin-top:14px;color:#9fc0d8;letter-spacing:3px;text-shadow:0 4px 20px rgba(0,0,0,.9)">${lineCnt} 条线路 · ${stCnt} 座车站 · 200× 垂直夸张</div>`;
    const pos = qp.get('wmpos') || 'bl';
    const css = { position:'fixed', zIndex:'99', pointerEvents:'none',
      fontFamily:'"PingFang SC","Microsoft YaHei",sans-serif' };
    if (pos === 'tl'){ css.left = '70px'; css.top = '64px'; }
    else if (pos === 'br'){ css.right = '70px'; css.bottom = '64px'; css.textAlign = 'right'; }
    else { css.left = '70px'; css.bottom = '64px'; }
    wm.style.cssText = Object.entries(css).map(([k,v]) => `${k.replace(/[A-Z]/g, m => '-' + m.toLowerCase())}:${v}`).join(';');
    document.body.appendChild(wm);
  }

  // 暴露渲染器句柄，供 8K 出图脚本调用
  window.__poster = { renderer, camera, scene, controls, renderFrame,
    getWorld: () => world, getLines: () => lineGroups,
    state, rebuild, populateSelectors, focusBridge, METRO_DATA, stopCruise };

  // 强制渲染几帧并标记就绪（供 headless 判断）
  let n = 0;
  const tick = () => {
    renderFrame(0.016);
    if (++n < 5) requestAnimationFrame(tick);
    else { window.__posterReady = true; document.title = 'POSTER_READY · ' + document.title; }
  };
  tick();
})();